['Here is a rough start in C for your requirements using pthreads for thread safety, curl for remote logging over HTTP/HTTPS, and a simplified version of an event-based system to allow for runtime configuration updates. 

```C
#include <stdio.h>
#include <pthread.h>
#include <curl/curl.h>
#include <time.h>
#include <string.h>

// Define log levels
typedef enum {INFO, DEBUG, WARNING, ERROR} LogLevel;

// Log message structure
typedef struct {
    time_t timestamp;
    LogLevel level;
    char message[256];
} LogMessage;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Create a new log message
LogMessage* create_log_message(LogLevel level, const char* fmt, ...) {
    va_list args;
    va_start(args, fmt);

    LogMessage* msg = malloc(sizeof(LogMessage));
    msg->timestamp = time(NULL);
    msg->level = level;
    vsnprintf(msg->message, sizeof(msg->message), fmt, args);

    va_end(args);

    return msg;
}

// Write a log message to a local file
void write_to_file(LogMessage* msg) {
    pthread_mutex_lock(&lock);

    FILE *logFile = fopen("app.log", "a");
    if (logFile == NULL) {
        return;
    }

    char timeString[20];
    strftime(timeString, sizeof(timeString), "%Y-%m-%d %H:%M:%S", localtime(&msg->timestamp));
    fprintf(logFile, "[%s] [%s]: %s\n", timeString, get_level_string(msg->level), msg->message);

    fclose(logFile);
    pthread_mutex_unlock(&lock);
}

// Write a log message to a remote service
void write_to_remote(LogMessage* msg) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if(curl) {
        char url[256];
        snprintf(url, sizeof(url), "https://yourloggingservice.com/%s", get_level_string(msg->level));

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, msg->message);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
}

// Get the string representation of a log level
const char* get_level_string(LogLevel level) {
    switch (level) {
        case INFO: return "INFO";
        case DEBUG: return "DEBUG";
        case WARNING: return "WARNING";
        case ERROR: return "ERROR";
        default: return "";
    }
}
```
For a real-world application, you'd want to make these improvements:

