const AWS = require('aws-sdk');
const fs = require('fs').promises;
const crypto = require('crypto');
const LRU = require('lru-cache');
const pino = require('pino');

// Initialize logger and cache
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });
const cache = new LRU({ max: 500, length: (value, key) => value.length, dispose: (key, n) => n.close() });

// Initialize AWS S3 service
AWS.config.update({ region: 'us-west-2' }); // Set your AWS Region here
const s3 = new AWS.S3();

async function getFile(bucketName, key) {
  try {
    let data = cache.get(key);

    if (!data) {
      const file = await s3.getObject({ Bucket: bucketName, Key: key }).promise();
      data = JSON.parse(file.Body.toString()); // Assuming files are stored in JSON format
      cache.set(key, data);
    }

    return { fileData: data, hash: crypto.createHash('md5').update(JSON.stringify(data)).digest("hex") };
  } catch (error) {
    logger.error({ error, bucketName, key }, 'Error getting file from S3');
    throw new Error('Failed to get file from S3');
  }
}

async function validateFileSchema(fileData) {
  // Add your schema validation logic here
  return true;
}

async function processFiles(files, bucketName) {
