function updateFieldsAndExtractBooks(resourceID, dialogFieldNames, url, text) {
    return new Promise((resolve, reject) => {
        let updatedDialogFields = {};
        let bookCounts = {};

        // Fetch dialog field metadata from API
        fetch(url)
            .then(response => response.json())
            .then(data => {
                for (let field of dialogFieldNames) {
                    if (field in data) {
                        updatedDialogFields[field] = data[field];
                    } else {
                        reject(new Error(`Could not find metadata for field: ${field}`));
                    }
                }

                // Extract book mentions from text
                let booksInText = text.match(/Old Testament Books go here/g);
                if (booksInText) {
                    for (let book of booksInText) {
                        if (!(book in bookCounts)) {
                            bookCounts[book] = 0;
                        }
                        bookCounts[book]++;
                    }
                } else {
                    reject(new Error('Could not find any Old Testament Books in text.'));
                }

                resolve({updatedDialogFields, bookCounts});
            })
            .catch(err => reject(err));
    });
}
