```javascript
// Require necessary dependencies
const fs = require('fs');
const path = require('path');
const axios = require('axios');
const express = require('express');
const bodyParser = require('body-parser');

// Initialize Express app
const app = express();
app.use(bodyParser.json());

// Load and execute functions from multiple directories recursively
function loadFunctionsFromDirectory(directoryPath) {
    const files = fs.readdirSync(directoryPath);

    for (const file of files) {
        const filePath = path.join(directoryPath, file);
        const stats = fs.statSync(filePath);

        if (stats.isDirectory()) {
            loadFunctionsFromDirectory(filePath);
        } else if (path.extname(file) === '.js') {
            require(filePath); // This will execute the function
        }
    }
}

// Fetch dynamic configuration parameters from an external RESTful API
axios.get('http://external-api/config').then((response) => {
    global.config = response.data;
}).catch((error) => {
    console.log(`Failed to fetch configurations: ${error}`);
});

// Function execution route
app.post('/execute', (req, res) => {
    const functionsToExecute = req.body.functions;

    for (const func of functionsToExecute) {
        try {
            // Assuming that each function is a named export from its respective module
            require(`./functions/${func}`)(); 
            res.status(200).send('Function executed successfully');
        } catch (error) {
            console.log(`Failed to execute ${func}: ${error}`);
            res.status(500).send('Internal server error');
        }
    }
});

// Start the express app on port 3000
app.listen(3000, () => {
    console.log("Server running on port 3000");
});
