    if (sem_init(&sem, 0, 1) == -1) {
        printf("Semaphore initialization failed\n");
        exit(EXIT_FAILURE);
    }

    ClinicStatus update;
    MYSQL *conn = NULL;

    // Acquire lock to ensure thread safety
    pthread_mutex_lock(&lock);

    // Acquire semaphore for synchronization
    if (sem_wait(&sem) == -1) {
        printf("Semaphore wait failed\n");
        exit(EXIT_FAILURE);
    }

    conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, "host", "user", "passwd", "dbname", 0, NULL, CLIENT_MULTI_STATEMENTS)) {
        printf("Failed to connect to database: Error: %s\n", mysql_error(conn));
    } else {
        char query[1024];
        sprintf(query, "UPDATE clinics SET status='%s' WHERE id=%d;", status, clinic_id);

        // Begin transaction to ensure data integrity
        if (mysql_autocommit(conn, 0) != 0 || mysql_query(conn, "BEGIN") != 0) {
            printf("Failed to start a transaction: %s\n", mysql_error(conn));
        } else {
            // Execute query and commit transaction
            if (mysql_query(conn, query) == 0 && mysql_commit(conn) == 0) {
                update.clinic_id = clinic_id;
                strncpy(update.status, status, sizeof(update.status));
            } else {
                printf("Failed to execute query or commit transaction: %s\n", mysql_error(conn));
                // Rollback the transaction in case of failure
                mysql_rollback(conn);
            }
        }
    }

    // Release semaphore for other threads after use
    if (sem_post(&sem) == -1) {
        printf("Semaphore post failed\n");
    }
    pthread_mutex_unlock(&lock);

    return update;
}
```
Remember to replace "host", "user", "passwd", and "dbname" with your actual database connection information. Also, this example does not include error handling for all edge cases mentioned in the problem statement such as invalid clinic IDs or network timeouts, which would require additional code specific to your application requirements.
