typedef struct Transaction {
    int age;
    int count;
    double weightedSum;
} Transaction;

Transaction* createTransaction(int age, int count, double weightedSum) {
    Transaction* transaction = malloc(sizeof(Transaction));
    if (!transaction) {
        return NULL; // out of memory
    }

    transaction->age = age;
    transaction->count = count;
    transaction->weightedSum = weightedSum;

    return transaction;
}

char* serializeTransaction(Transaction* transaction) {
    int size = sizeof(int)*2 + sizeof(double);
    char* buffer = malloc(size + 1); // extra byte for null terminator
    if (!buffer) {
        return NULL; // out of memory
    }

    memcpy(buffer, &transaction->age, sizeof(int));
    memcpy(buffer + sizeof(int), &transaction->count, sizeof(int));
    memcpy(buffer + 2*sizeof(int), &transaction->weightedSum, sizeof(double));

    buffer[size] = '\0'; // null terminate the string for easier debugging
    return buffer;
}
```

2. Implementing a connection pool:
```c
// This is an oversimplification. In practice you'd use a real library or framework that supports connection pools.
#define MAX_CONNECTIONS 100
typedef struct ConnectionPool {
    void* connections[MAX_CONNECTIONS];
    int next;
} ConnectionPool;

ConnectionPool createConnectionPool(void** connections) {
    ConnectionPool pool;

    memcpy(pool.connections, connections, sizeof(void*) * MAX_CONNECTIONS);
    pool.next = 0;

    return pool;
}

void* getNextConnection(ConnectionPool* pool) {
    void* connection = pool->connections[pool->next];
    pool->next = (pool->next + 1) % MAX_CONNECTIONS;

    return connection;
}
```

3. Implementing asynchronous database operations:
