// A simple attack model
struct Attack {
    std::string name;
    int cooldown; // in milliseconds
};

class GameCharacter {
private:
    std::vector<Attack> attacks;
    std::chrono::steady_clock::time_point lastUsedTime = std::chrono::steady_clock::now();
    std::mutex mtx; // for thread safety
public:
    void addAttack(const Attack& attack) {
        attacks.push_back(attack);
    }

    Attack selectAttack() {
        std::lock_guard<std::mutex> guard(mtx); // to ensure thread safety

        auto currentTime = std::chrono::steady_clock::now();
        for (const auto& attack : attacks) {
            if ((currentTime - lastUsedTime) >= std::chrono::milliseconds(attack.cooldown)) {
                lastUsedTime = currentTime; // update the time of last use
                return attack;
            }
        }

        throw std::runtime_error("All attacks are on cooldown.");
    }
};
```

