using System;
using System.Threading;
using System.Collections.Concurrent;
using System.Net.Http;
using Newtonsoft.Json;

public class DynamicRandomValueGenerator : IDisposable
{
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly ConcurrentQueue<Thread> _threadPool = new ConcurrentQueue<Thread>();
    private readonly CancellationTokenSource _cts = new CancellationTokenSource();
    private bool _disposed;

    public DynamicRandomValueGenerator()
    {
        // Initialize thread pool based on expected load and available resources.
        for (int i = 0; i < optimalNumberOfThreads; ++i)
        {
            var thread = new Thread(() => GenerateValues(optimalNumberOfThreads));
            _threadPool.Enqueue(thread);
            thread.Start();
        }
    }

    public void Dispose()
    {
        if (_disposed) return;
        _cts.Cancel();

        // Wait for all threads to finish before disposing.
        foreach (var thread in _threadPool)
        {
            thread.Join();
        }

        _httpClient.Dispose();
        _disposed = true;
    }

    private async void GenerateValues(int optimalNumberOfThreads)
    {
        while (!_cts.Token.IsCancellationRequested)
        {
            try
            {
                // Fetch range parameters dynamically from the external API.
                var response = await _httpClient.GetAsync("externalApiEndpoint", _cts.Token);
                if (response.IsSuccessStatusCode)
                {
                    var rangeParameters = JsonConvert.DeserializeObject<RangeParameters>(await response.Content.ReadAsStringAsync());

