            catch (HttpRequestException ex)
            {
                // Handle network issues, e.g., retries with exponential backoff.
            }
        }
    }

    private float GetRandomValue(RangeParameters rangeParams)
    {
        var random = new Random();

        if (rangeParams.Inclusive)
        {
            return (float)(random.NextDouble() * (rangeParams.Max - rangeParams.Min) + rangeParams.Min);
        }

        return (float)(random.NextDouble() * (rangeParams.Max - rangeParams.Min - 1) + rangeParams.Min + 1);
    }

