    Task<string> GetIVAsync();
}

public interface IExternalServiceValidator
{
    Task<bool> IsValidDataAsync(List<int> data);
}

public class ProcessEncryptedData
{
    private readonly ISecureStorage secureStorage;
    private readonly IExternalServiceValidator externalServiceValidator;

    public ProcessEncryptedData(ISecureStorage secureStorage, IExternalServiceValidator externalServiceValidator)
    {
        this.secureStorage = secureStorage;
        this.externalServiceValidator = externalServiceValidator;
    }

    public async Task<ProcessEncryptedDataResult> ProcessAsync(string encryptedBase64String)
    {
        var result = new ProcessEncryptedDataResult();

        try
        {
            // Fetch the key and IV from secure storage.
            var key = await secureStorage.GetKeyAsync();
            var iv = await secureStorage.GetIVAsync();

            // Decrypt the encrypted message.
            string decryptedString;
            using (TripleDESCryptoServiceProvider tdesAlgorithm = new TripleDESCryptoServiceProvider())
            {
                tdesAlgorithm.Key = Convert.FromBase64String(key);
                tdesAlgorithm.IV = Convert.FromBase64String(iv);

                ICryptoTransform decryptor = tdesAlgorithm.CreateDecryptor();
                byte[] encryptedBytes = Convert.FromBase64String(encryptedBase64String);
                byte[] decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

                decryptedString = Encoding.UTF8.GetString(decryptedBytes);
            }

            // Parse the plaintext message into a list of integers.
            List<int> dataList;
            try
            {
                dataList = JsonConvert.DeserializeObject<List<int>>(decryptedString);
            }
            catch (JsonReaderException)
            {
                throw new FormatException("Failed to parse decrypted message into a list of integers.");
            }

            // Validate the data with an external service if necessary.
            bool isValidData = await externalServiceValidator.IsValidDataAsync(dataList);
            if (!isValidData)
            {
                result.Success = false;
                result.ErrorMessage = "The decrypted data failed validation against the external service.";
                return result;
            }

            // Find the maximum value in the list of integers.
            int maxValue = dataList.Max();

            result.Success = true;
            result.MaxValue = maxValue;
        }
        catch (Exception ex)
        {
            result.Success = false;
            result.ErrorMessage = $"An error occurred while processing the encrypted data: {ex.Message}";
        }

        return result;
    }
}
```
']

