['Below is a sample Java service that uses ObjectInputStream to perform deserializing objects from byte arrays or files while also handling exceptions like ClassNotFoundException. It utilizes a third-party library for handling external data sources, integrates custom class loader, provides concurrency safety and caching mechanism. Logging has been incorporated into the code for all deserialization activities:

```java
import java.io.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;
import java.util.logging.Logger;

public class DeserializeService {
    private static final Logger logger = Logger.getLogger(DeserializeService.class.getName());

    private CustomClassLoader customClassLoader;  // Assume this is implemented, see below
    private ConcurrentHashMap<String, Object> cache = new ConcurrentHashMap<>();

    public DeserializeService() {
        this.customClassLoader = new CustomClassLoader(Thread.currentThread().getContextClassLoader());
    }

    public synchronized <T> T deserializeFromFile(String filePath, Class<T> clazz) throws IOException, ClassNotFoundException {
        FileInputStream fis = new FileInputStream(filePath);
        Object obj = deserializeFromStream(fis, clazz);
        fis.close();

        return clazz.cast(obj);
    }

    public synchronized <T> T deserializeFromByteArray(byte[] bytes, Class<T> clazz) throws IOException, ClassNotFoundException {
        ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
        Object obj = deserializeFromStream(bais, clazz);
        bais.close();

        return clazz.cast(obj);
    }

    private synchronized <T> T deserializeFromStream(InputStream is, Class<T> clazz) throws IOException, ClassNotFoundException {
        Object obj;
        try (ObjectInputStream ois = new CustomObjectInputStream(is)) {  // Use custom ObjectInputStream
            String className = ois.readUTF();

            if (!cache.containsKey(className)) {
                logger.log(Level.INFO, "Loading class: {0}", className);
                Class<?> loadedClass = this.customClassLoader.loadClass(className);  // Use custom class loader for safe loading

                cache.putIfAbsent(className, loadedClass);
            }

            obj = ois.readObject();
        }

        return clazz.cast(obj);
    }

    private static class CustomObjectInputStream extends ObjectInputStream {
        public CustomObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            // Implement logic to validate classes and prevent security issues
            return super.resolveClass(desc);
        }
    }

    private static class CustomClassLoader extends ClassLoader {  // Custom class loader for safe loading
         public CustomClassLoader(ClassLoader parent) {
             super(parent);
         }

         @Override
         protected synchronized Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
             // Implement logic to validate classes and prevent security issues
             return super.loadClass(name, resolve);
         }
    }
}
```
Please note that custom class loading is a critical part of this implementation and should be implemented based on specific requirements for the third-party library used in your scenario. This example merely provides a skeleton to work off of.
