["Here is a high-level implementation using NodeJS with third-party libraries such as `axios` for API requests, `crypto-js` for encryption, `bull` for queue system, and `winston` for logging:

```javascript
const fs = require('fs');
const os = require('os');
const crypto = require('crypto-js');
const axios = require('axios');
const { exec } = require('child_process');
const Queue = require('bull');
const winston = require('winston');

// Configure logger to log to file and console
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log' }),
    new winston.transports.Console()
  ]
});

// Create queue for handling requests in parallel
const modifyConfigQueue = new Queue('modify config');

function modifyAndEncrypt(apiUrl, secretKey) {
  // Fetch configuration data
  axios.get(apiUrl).then((response) => {
    const { password } = response.data;

    // Encrypt the password
    const cipherText = crypto.AES.encrypt(password, secretKey).toString();

    // Modify and write to a new file
    const timestamp = Date.now();
    const filename = `config_${timestamp}.txt`;

    modifyConfigQueue.add({
      filename,
      cipherText
    });
  }).catch((error) => {
    logger.log('error', `Error fetching configuration data: ${error}`);
  });
}

// Processor for modifying the config file and writing to a new one
modifyConfigQueue.process(async (job, done) => {
  const { filename, cipherText } = job.data;

  // Check if file already exists
  fs.access(filename, fs.F_OK, (err) => {
    if (!err) {
      logger.log('error', 'File already exists');
      return done(new Error('File already exists'));
    }

    // Modify configuration file with the fetched values
    exec(`sed -i 's/<password>/${cipherText}/g' config.txt`, (error) => {
      if (error) {
        logger.log('error', `Error modifying configuration: ${error}`);
        return done(new Error('Error modifying configuration'));
      }

      // Write to a new file
      fs.writeFile(filename, os.EOL + cipherText, (err) => {
        if (err) {
          logger.log('error', `Error writing to new file: ${err}`);
          return done(new Error('Error writing to new file'));
        }

        done();
      });
    });
  });
});
```
This is a high-level implementation and would need further development for full features. Please adapt it according to your needs, as the specifics of your project may require different approaches or third-party libraries.
"]

