    char* key;
    void* value;
} Entry;

Entry* table;
size_t capacity, size;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert(const char* key, void* value) {
    pthread_mutex_lock(&lock);

    if (size >= capacity * 0.75) { // load factor > 75%
        resize();
    }

    uint64_t hash = hash_function(key);
    size_t index = hash % capacity;

    while (table[index].key != NULL && strcmp(table[index].key, "") != 0) { // collision resolution using linear probing
        if (strcmp(table[index].key, key) == 0) { 
            break;
        }

        index = (index + 1) % capacity;
    }

    table[index].key = strdup(key); // duplicate the string to ensure immutability
    table[index].value = value;
    ++size;

    pthread_mutex_unlock(&lock);
}
```
