    if (newEvent == NULL) {
        // Out of memory error handling
        return;
    }

    pthread_mutex_lock(&mutex);
    if (nextIndex >= arraySize) {
        size_t newSize = arraySize ? arraySize * 2 : 16;
        Event** newArray = realloc(eventsArray, sizeof(Event*) * newSize);

        if (newArray == NULL) {
            // Out of memory error handling
            pthread_mutex_unlock(&mutex);
            free(newEvent);
            return;
        }

        eventsArray = newArray;
        arraySize = newSize;
    }

    newEvent->timestamp = time(NULL);
    newEvent->eventType = rand() % (MAX_EVENT_TYPE - MIN_EVENT_TYPE + 1) + MIN_EVENT_TYPE; // Assuming MIN and MAX event types are defined
    int retries = 0;

    do {
        if (fetchMetadata(&newEvent->metadata, newEvent->eventType)) {
            free(newEvent);
            pthread_mutex_unlock(&mutex);
            ++retries;
            // Sleep for exponentially longer durations after each retry to avoid flooding the API with requests
            sleep(pow(2, retries)); 
        } else {
            break;
        }
    } while (retries < MAX_RETRIES); // MAX_RETRIES is a defined constant

    eventsArray[nextIndex++] = newEvent;
