['Below is an example solution. It is important to note that this is just an implementation proposal, actual use-case might require additional features or modifications based on specific project requirements. 

```csharp
using System;
using System.Threading;
using System.Collections.Generic;
using System.Net.Http;
using System.Text.Json;
using System.Linq;

public class DynamicRandomValueGenerator
{
    private readonly HttpClient _httpClient = new HttpClient();
    private static SemaphoreSlim semaphore = new SemaphoreSlim(1, 1);
    private int[] range = new int[2];

    public async void FetchConfig()
    {
        try
        {
            var response = await _httpClient.GetAsync("config_service_url");
            if (response.IsSuccessStatusCode)
            {
                var contentStream = await response.Content.ReadAsStringAsync();
                var newRange = JsonSerializer.Deserialize<int[]>(contentStream);

                // Use a semaphore to protect the range from being modified concurrently
                semaphore.Wait();
                try 
                {
                    this.range = newRange;
                }
                finally
                {
                    semaphore.Release();
                }
            }
        }
        catch (HttpRequestException) // Handle network issues, service disruptions etc..
        {
            Console.WriteLine("Error fetching config from the server");
        }
    }

    public int GenerateRandomInt(bool inclusive = false)
    {
        if (!inclusive && range[0] + 1 >= range[1]) 
            throw new InvalidOperationException("Invalid range for exclusive random generation.");

        semaphore.Wait();
        var value = 0;
        try
        {
            Random rand = new Random();
            if (inclusive)
                value = rand.Next(range[0], range[1] + 1); // Inclusive bounds
            else 
                value = rand.Next(range[0] + 1, range[1]); // Exclusive bounds
        }
        finally 
        {
            semaphore.Release();
        }

        return value;
    }

    public float GenerateRandomFloat()
    {
        if (range[0] >= range[1]) 
            throw new InvalidOperationException("Invalid range for random float generation.");

        semaphore.Wait();
        var value = 0f;
        try
        {
            Random rand = new Random();
            // Generate random floats in the given range
            var randomValue = (float)rand.NextDouble(); 
            var diff = (float)(range[1] - range[0]);
            value = (randomValue * diff) + (float)range[0];
        }
        finally 
        {
            semaphore.Release();
        }

        return value;
    }

    public string GetRange()
    {
        // Return a copy of the current range to avoid race conditions
        var _range = new int[2];
        semaphore.Wait();
        try 
        {
            Array.Copy(this.range, _range, this.range.Length);
        }
        finally 
        {
            semaphore.Release();
        }

        return $"Range: [{_range[0]}, {_range[1]}]";
    }
}
```
This solution uses a SemaphoreSlim to protect the range from being modified concurrently, and an HttpClient for fetching configuration updates from a remote service. It also includes fail-safe handling for network latency or data consistency issues during state transitions by using a `SemaphoreSlim`. This class is designed to be easily testable because it has a clear, single responsibility - generating random numbers within a specified range.
']

