```c
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <unistd.h>

// Structure to hold encryption key and data chunks
typedef struct chunk {
    unsigned char *key;
    unsigned char *data;
    size_t length;
} chunk_t;

// Encrypt a single chunk of data using AES-256
void encrypt(chunk_t *c) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char ciphertext[128];
    int len, ciphertext_len;

    // Initialize the encryption context
    EVP_EncryptInit(ctx, EVP_aes_256_cbc(), c->key, NULL);

    // Encrypt the data chunk
    EVP_EncryptUpdate(ctx, ciphertext, &len, c->data, c->length);
    ciphertext_len = len;

    // Finalize encryption and clean up
    EVP_EncryptFinal(ctx, ciphertext + len, &len);
    ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx);
}

// Thread function to encrypt data chunks
void *thread_func(void *arg) {
    chunk_t *c = (chunk_t *) arg;
    encrypt(c);
    pthread_exit(NULL);
}

int main(int argc, char **argv) {
    // Parse command line arguments and configuration file here...

    // Load chunks from multiple sources...
    chunk_t chunks[10];  // Dummy array of chunks

    pthread_t threads[10];  // Array to hold thread IDs
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_func, &chunks[i]);
    }

    // Wait for all threads to complete...
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
