} Record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // For thread safety

void fillRecord(Record *record, ApiResponse *resp) {
    pthread_mutex_lock(&lock);  // Lock before modifying shared state

    record->timestamp = time(NULL);
    record->eventType = resp->eventType;
    record->metadata = strdup(resp->metadata);

    free(resp);

    pthread_mutex_unlock(&lock);  // Unlock after modifying shared state
}

void fillRecords(Record *records, size_t num) {
