```C
#include <pthread.h>
#include <semaphore.h>
#include <libpq-fe.h>

typedef struct {
    char *update_query;
    PGconn *connection;
    sem_t *semaphore;
} updateParams_t;

void* updateClinicStatus(void *arg) {
    updateParams_t *params = (updateParams_t*) arg;
    // Acquire the semaphore
    if (sem_wait(params->semaphore) < 0) {
        printf("Semaphore wait failed.\n");
        return NULL;
    }

    PGresult *res = PQexec(params->connection, params->update_query);

    if (PQresultStatus(res) != PGRES_COMMAND_OK) {
        printf("Update failed: %s", PQerrorMessage(params->connection));
        PQclear(res);
        sem_post(params->semaphore); // Release the semaphore
        return NULL;
    }

    PQclear(res);
    printf("Update succeeded.\n");

    if (sem_post(params->semaphore) < 0) {
        printf("Semaphore post failed.\n");
    }

    return NULL;
}
```
In a production environment, you would need to expand this codebase significantly to handle all the requirements mentioned in your task. This includes but is not limited to, error handling, retry logic for network failures, logging, handling of multiple instances and caching layer, decoupling with message queue system, configuration options, etc.
