```csharp
using System;
using System.Data;
using System.Collections.Concurrent;
using System.Threading.Tasks;
using Dapper;
using Npgsql;

public class DataIngestor : IDisposable
{
    private readonly BlockingCollection<byte[]> _queue = new();
    private Task _consumerTask;
    private volatile bool _isDisposed;

    public DataIngestor()
    {
        // Start a task that will consume items from the queue and process them
        _consumerTask = Task.Run(() => Consume());
    }

    public void IngestData(byte[] data)
    {
        if (_isDisposed) throw new ObjectDisposedException(nameof(DataIngestor));

        // Enqueue the data for processing by the consumer task
        _queue.Add(data);
    }

    private async Task Consume()
    {
        using var connection = new NpgsqlConnection("your_connection_string");

        await connection.OpenAsync();

        foreach (var data in _queue.GetConsumingEnumerable())
        {
            // Process the data here, for example save it to a PostgreSQL database
            const string sql = "INSERT INTO your_table(data) VALUES (@Data)";

            await connection.ExecuteAsync(sql, new { Data = data });
        }
    }

    public void Dispose()
    {
        if (_isDisposed) return;

        _queue.CompleteAdding();

        // Wait for the consumer task to finish
        _consumerTask?.Wait();

        _isDisposed = true;
    }
}
```
This code only shows how you might start creating a data ingestion pipeline in C#, and does not handle many edge cases or complex requirements from your list. You would need to expand this concept with more features like exception handling, logging, backpressure mechanisms, retry logic for failed uploads, schema changes, multi-tenancy etc.
