    const stats = await fs.stat(req.file.path);
    if (!stats.isFile()) throw new Error('Uploaded file is not a valid image');

    // Load the image using Sharp and process it
    let processedImage = sharp(req.file.path)
      .resize({ width: 500, height: 500 }) // Resize to 500x500 pixels
      .grayscale() // Convert to grayscale
      .jpeg(); // Convert to JPEG format

    // Save the processed image to disk
    await processedImage.toFile(`processed/${req.file.filename}`);

    res.send('Image processed successfully');
  } catch (error) {
    console.error(error);
    res.status(500).send('An error occurred while processing the image');
  }
});

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```
This code starts an Express server that listens for POST requests at /process-image. It uses Multer to handle the file upload and Sharp to process the image. The processed image is then saved to disk.

