```c
#include <openssl/evp.h>
#include <openssl/err.h>
#include <string.h>

// Function to initialize AES-256-CBC cipher with user provided passwords
int aes_init(const char* username, const char* password) {
    // Create and initialize the context
    EVP_CIPHER_CTX *ctx;

    if(!(ctx = EVP_CIPHER_CTX_new())) {
        ERR_print_errors_fp(stderr);
        return 0;
    }

    // Convert password to key and iv using PBKDF2-HMAC-SHA1
    unsigned char* key = malloc(EVP_MAX_KEY_LENGTH);
    unsigned char* iv = malloc(EVP_MAX_IV_LENGTH);

    if(!EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha1(), NULL, (unsigned char*)password, strlen(password), 1, key, iv)) {
        ERR_print_errors_fp(stderr);
        return 0;
    }

    // Initialize cipher context for encryption with given key and iv.
    if(!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        ERR_print_errors_fp(stderr);
        return 0;
    }

    // Clean up
    free(key);
    free(iv);
    EVP_CIPHER_CTX_free(ctx);

    return 1;
}
```
Please note that actual implementation would require handling of network requests, error handling and code optimizations. 

Also, this example uses PBKDF2-HMAC-SHA1 for key derivation, but it's recommended to use a custom hash function to ensure constant time execution against timing attacks. This is left as a challenge to be implemented.
