```csharp
using System;
using System.Collections.Generic;
using System.Threading;
using System.Data;

public class DynamicRandomValueGenerator {
    private List<ExternalSource> dataSources = new List<ExternalSource>(); // list of all external sources to pull data from

    public void AddDataSource(ExternalSource source) {
        this.dataSources.Add(source);
    }

    public double GetRandomDoubleInRange(int rangeId) {
        Range range = this.GetRangeFromAllSources(rangeId); // get the range from all data sources, priority order being defined by data source priority or age

        if (range != null && range is DoubleRange) {
            return ((DoubleRange)range).GenerateRandomValue();
        } else {
            throw new Exception("Invalid range type"); // handle invalid ranges here
        }
    }

    public int GetRandomIntInRange(int rangeId) {
        Range range = this.GetRangeFromAllSources(rangeId); // get the range from all data sources, priority order being defined by data source priority or age

        if (range != null && range is IntegerRange) {
            return ((IntegerRange)range).GenerateRandomValue();
        } else {
            throw new Exception("Invalid range type"); // handle invalid ranges here
        }
    }

    private Range GetRangeFromAllSources(int rangeId) {
        foreach (ExternalSource source in this.dataSources) {
            try {
                return source.GetLatestRangeById(rangeId);
            } catch (DataSourceNotAvailableException e) {
                // handle the exception here, for example fall back to local data sources or use a default range value
            }
        }

        throw new Exception("All data sources are unavailable"); // all sources failed
    }
}

public abstract class Range {}

public class DoubleRange : Range {
    private double min;
    private double max;

    public DoubleRange(double min, double max) {
        this.min = min;
        this.max = max;
    }

    public double GenerateRandomValue() {
        Random rand = new Random();
        return (rand.NextDouble() * (this.max - this.min)) + this.min;
    }
}

public class IntegerRange : Range {
    private int min;
    private int max;

    public IntegerRange(int min, int max) {
        this.min = min;
        this.max = max;
    }

    public int GenerateRandomValue() {
        Random rand = new Random();
        return rand.Next(this.min, this.max);
    }
}

public class ExternalSource {}
``` 

This is a very basic example and does not handle many things such as data source prioritization, fallback to local sources when all sources are unavailable, role-based access control or machine learning model integration. It also doesn't include error handling for invalid range types or failures in fetching ranges from data sources.

