import asyncio
from collections import deque
from abc import ABC, abstractmethod

# MetricData class definition
class MetricData:
    def __init__(self, timestamp, name, value, source_id):
        self.timestamp = timestamp
        self.name = name
        self.value = value
        self.source_id = source_id

# Data Ingestion Pipeline with asynchronous messaging queue 
class MessageQueue:
    def __init__(self, capacity=100):
        self._queue = deque(maxlen=capacity)

    async def put(self, item):
        if len(self._queue) == self._queue.maxlen:
            await self._remove_oldest()
        self._queue.append(item)

    async def get(self):
        while not self._queue:
            await asyncio.sleep(0.1)
        return self._queue.popleft()

# Base class for processing units
class ProcessUnit(ABC):
    @abstractmethod
    def process(self, data):
        pass

# Example of a filter unit
class FilterUnit(ProcessUnit):
    def __init__(self, filter_func):
        self.filter_func = filter_func

    def process(self, metric_data):
        return [md for md in metric_data if self.filter_func(md)]

# Real-Time Processing Engine 
class Processor:
    def __init__(self):
        self._units = []

    def add_unit(self, unit):
        self._units.append(unit)

    def process(self, metric_data):
        for unit in self._units:
            metric_data = unit.process(metric_data)
        return metric_data
```
