import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.boot.SpringApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.data.redis.connection.lettuce.LettuceConnectionFactory;
import org.springframework.web.client.RestTemplate;
import org.springframework.cache.annotation.EnableCaching;

@SpringBootApplication
@RestController
@EnableCaching
public class Application {

    @Autowired
    private RestTemplate restTemplate;

    @Bean
    public LettuceConnectionFactory redisConnectionFactory() {
        return new LettuceConnectionFactory();
    }

    @GetMapping("/{id}")
    @Cacheable(value = "externalApiData", key = "#id")
    public String getExternalApiData(@PathVariable("id") String id) {
        return restTemplate.getForObject("http://example.com/api/" + id, String.class);
    }

    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}
```
This is a very simplified example and a real-world application would be much more complex. As you can see, the RestTemplate bean is used to make HTTP requests to an external API. The `@Cacheable` annotation on the method indicates that results from this method should be cached using Redis. This way, if the same ID is requested multiple times, the response will be pulled from the cache instead of making a new request to the API.

