public class MarketDataService
{
    private readonly List<IMarketDataProvider> _providers;

    public MarketDataService(List<IMarketDataProvider> providers)
    {
        _providers = providers;
    }

    public async Task<Stock> GetStockAsync(string symbol)
    {
        var tasks = _providers.Select(p => p.GetStockAsync(symbol)).ToList();

        while (tasks.Any())
        {
            var completedTask = await Task.WhenAny(tasks);
            tasks.Remove(completedTask);

            try
            {
                return await completedTask;
            }
            catch
            {
                // Log the error, or retry if necessary
            }
        }

        throw new Exception("All providers failed to respond");
    }
}
```
