public class StockRepository
{
    private readonly ConnectionMultiplexer _redis;

    public StockRepository(ConnectionMultiplexer redis)
    {
        _redis = redis;
    }

    public async Task<Stock> GetAsync(string symbol)
    {
        var db = _redis.GetDatabase();

        var value = await db.StringGetAsync(symbol);

        if (value.HasValue)
        {
            return JsonConvert.DeserializeObject<Stock>(value);
        }

        // Load data from the data provider
        var stock = await _marketDataService.GetStockAsync(symbol);

        // Cache it for 1 hour
        await db.StringSetAsync(symbol, JsonConvert.SerializeObject(stock), TimeSpan.FromHours(1));

        return stock;
    }
}
