3. Distributed lock:
```csharp
public class RedlockDistributedLock : IDistributedLock
{
    private readonly IRedlock _redlockFactory;

    public RedlockDistributedLock(IRedlock redlockFactory)
    {
        _redlockFactory = redlockFactory;
    }

    public async Task<IDisposable> AcquireLockAsync()
    {
        var redlock = await _redlockFactory.CreateLockAsync("resource", TimeSpan.FromSeconds(10));

        if (redlock.Status == RedlockStatus.Acquired)
        {
            return new DisposableAction(() => redlock.Dispose());
        }

        throw new Exception("Failed to acquire lock");
    }
}
```
