```java
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.web.bind.annotation.*;
import co.elastic.clients.elasticsearch._types.SortOrder;
import co.elastic.clients.elasticsearch.core.SearchRequest;
import co.elastic.clients.elasticsearch.core.search.Hit;
import co.elastic.clients.json.jackson.JacksonJsonpMapper;
import co.elastic.clients.transport.ElasticsearchTransport;
import co.elastic.clients.elasticsearch.ElasticsearchClient;
import co.elastic.clients.util.ObjectBuilder;

@RestController
public class LogIngestionController {
    private final ElasticsearchClient esClient;

    public LogIngestionController(ElasticsearchTransport transport) {
        this.esClient = new ElasticsearchClient(transport);
    }

    @PostMapping("/logs")
    public void ingestLog(@RequestBody String logData) throws IOException {
        // Ingest logs into Kafka topic for further processing
    }

    @KafkaListener(topics = "${kafka.topic}")
    public void processLog(String logData) throws Exception {
        // Process logs data here and send to Elasticsearch
        esClient.index(i -> i
                .index("logs-index")
                .document(ObjectBuilder.fromJson(logData, JacksonJsonpMapper.INSTANCE))
        );
    }
}

@RestController
public class LogSearchController {
    private final ElasticsearchClient esClient;

    public LogSearchController(ElasticsearchTransport transport) {
        this.esClient = new ElasticsearchClient(transport);
    }

    @GetMapping("/logs")
    public List<String> searchLogs(@RequestParam("query") String query) throws IOException {
        SearchRequest searchReq = SearchRequest.of(s -> s
                .index("logs-index")
                .query(q -> q
                        .bool(b -> b
                                .must(m -> m
                                        .match(ma -> ma
                                                .field("message")
                                                .query(query)
                                        )
                                )
                        )
                ).sort(so -> so.field(f -> f
                        .field("timestamp")
                        .order(SortOrder.Desc))
                ));

        List<String> logs = new ArrayList<>();
        for (Hit hit : esClient.search(searchReq, String.class).hits().hits()) {
            logs.add((String) hit.source());
        }

        return logs;
    }
}
```

This is a simplified solution and doesn't cover many aspects like connection pooling, error handling, observability and security. A fully featured system would require a much more complex codebase including configurations for Apache Kafka, Elasticsearch, Spring Boot Actuator, Prometheus, etc. Also, you would need to consider using other tools or frameworks based on your specific use case.
