const express = require('express');
const { Pool } = require('pg');
const axios = require('axios');
const amqp = require('amqplib/callback_api');
const app = express();
app.use(express.json());

// PostgreSQL connection pooling
const pgPool = new Pool({
  // Connection options
});

// Message Broker Setup using RabbitMQ
let amqpConn = null;
amqp.connect('amqp://localhost', (err, conn) => {
  if (!conn) {
    console.log(`Error connecting to RabbitMQ: ${err}`);
    process.exit(1);
  }

  amqpConn = conn;
  console.log('RabbitMQ connected');
});

// REST Endpoint for synchronizing data across different databases and third-party APIs
app.post('/sync', async (req, res) => {
  try {
    const thirdPartyApiData = await axios.get('<third-party-api-url>');
    const dbData = await pgPool.query('SELECT * FROM <table_name>'); // replace with actual query

    // Merge data from different sources
    const mergedData = { ...dbData, ...thirdPartyApiData };

    // Send synchronized data to the queue for further processing
    amqpConn.createChannel((err, ch) => {
      if (!ch) {
        console.log(`Error creating RabbitMQ channel: ${err}`);
        return;
      }

      const q = '<queue_name>'; // replace with actual queue name
      ch.assertQueue(q, { durable: false });
      ch.sendToQueue(q, Buffer.from(JSON.stringify(mergedData)));
      console.log(" [x] Sent %s", mergedData);
    });

    res.status(200).json({ message: 'Data synced successfully.' });
  } catch (error) {
    console.error('Error syncing data', error);
    res.status(500).send();
  }
});

// Start the server
const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Server is running on port ${port}`));
```
