```cpp
#include<iostream>
#include<vector>
#include<thread>
#include<mutex>
#include<condition_variable>

class DeviceStatusUpdate {
public:
    // methods for handling and processing metrics, logs, metadata...
private:
    std::string data;
};

// Buffer to store updates 
std::vector<DeviceStatusUpdate> buffer;
const int maxBufferSize = 10'000;

// Thread-safe operations using mutex and condition variables
std::mutex mtx;
std::condition_variable cv;
bool ready = false;

void producer() {
    for(int i=0; i<maxBufferSize; ++i) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, []{ return buffer.size() < maxBufferSize || ready; });
        if(ready){
            break;
        }
        DeviceStatusUpdate update;
        // Fill the update...
        buffer.push_back(update);
        lock.unlock();
        cv.notify_all();
    }
}

void consumer() {
    while (true) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, []{ return !buffer.empty() || ready; });
        if (ready && buffer.empty()) {
            break;
        }
        // Process the update...
        buffer.erase(buffer.begin());
        lock.unlock();
        cv.notify_all();
    }
}

int main() {
    std::thread producerThread(producer);
    std::thread consumerThread(consumer);

    producerThread.join();
    ready = true; // Signal consumers to stop processing updates
    cv.notify_all();

    consumerThread.join();
}
```
This code is a simple example of producer-consumer pattern using C++11 standard library threading facilities, which you may extend and customize according to your needs. Also, for database query optimization, error handling, encryption, monitoring, documentation etc., you would need to implement additional classes, functions, APIs, etc., that are far beyond the scope of a single code block.
