```java
import java.util.concurrent.*;
import org.apache.kafka.clients.producer.*;
import org.apache.kafka.common.serialization.StringSerializer;

public class HighPerformanceMiddleware {
    private final KafkaProducer<String, String> producer;
    private final ExecutorService executorService;

    public HighPerformanceMiddleware() {
        Properties props = new Properties();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        producer = new KafkaProducer<>(props);

        executorService = Executors.newFixedThreadPool(10); // create 10 threads in thread pool
    }

    public void sendData(String topic, String data) {
        ProducerRecord<String, String> record = new ProducerRecord<>(topic, data);
        producer.send(record, (metadata, exception) -> {
            if (exception != null) {
                // handle error
            } else {
                System.out.println("Data sent to Kafka topic: " + topic);
            }
        });
    }

    public void consumeData(String topic) {
        executorService.submit(() -> {
            try (KafkaConsumer<String, String> consumer = new KafkaConsumer<>(new Properties())) {
                consumer.subscribe(Collections.singletonList(topic));

                while (true) {
                    ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
                    for (ConsumerRecord<String, String> record : records) {
                        System.out.printf("offset = %d, key = %s, value = %s%n", record.offset(), record.key(), record.value());
                    }
                }
            } catch (WakeupException e) {
                // ignore for shutdown
            } finally {
                consumer.close();
            }
        });
    }

    public void close() {
        producer.close();
        executorService.shutdown();
    }
}
```
This is a very simplified example using Apache Kafka for messaging. Real-world applications would require more complexity, including error handling, data serialization/deserialization, and management of multiple threads and resources. This code does not cover all the aspects you mentioned such as cloud native deployments, compliance checks, monitoring tools, differential data sharing with partner institutions, differential storage options, security features etc. 

