```c
// Sample code in C using Boost.Asio
#include <boost/asio.hpp>

namespace ba = boost::asio;
using ba::ip::tcp;

void http_get(const std::string& server, const std::string& path) {
    try {
        ba::io_context io_context;

        tcp::resolver resolver(io_context);
        tcp::socket socket(io_context);

        ba::connect(socket, resolver.resolve(server, "http"));

        ba::streambuf request;
        std::ostream request_stream(&request);
        request_stream << "GET " << path << " HTTP/1.0\r\n";
        request_stream << "Host: " << server << "\r\n";
        request_stream << "Accept: */*\r\n";
        request_stream << "Connection: close\r\n\r\n";

        ba::write(socket, request);

        boost::asio::streambuf response;
        ba::read_until(socket, response, "\r\n");
        std::istream response_stream(&response);
        std::string http_version;
        response_stream >> http_version;
        unsigned int status_code;
        response_stream >> status_code;
        std::string status_message;
        std::getline(response_stream, status_message);

        if (!response_stream || http_version.substr(0, 5) != "HTTP/") {
            // handle invalid response error
        }
    } catch (std::exception& e) {
        // handle exception in request and response process
    }
}
