    unsigned char iv[EVP_MAX_IV_LENGTH];
} AES256Context;

AES256Context* aes256ContextCreate() {
    AES256Context *ctx = malloc(sizeof(AES256Context));
    ctx->ctx = EVP_CIPHER_CTX_new();
    return ctx;
}

void aes256InitializeKeyAndIV(AES256Context* ctx, unsigned char *keyData, int keyLen) {
    if (!RAND_bytes(ctx->iv, EVP_CIPHER_CTX_iv_length(ctx->ctx))) { /* Error handling */ }

    // Generate a secure random IV and store it in ctx->iv
    unsigned char *salt = NULL;
    if (!RAND_bytes(salt, 8)) { /* Error handling */ }

    if (!PKCS5_PBKDF2_HMAC(keyData, keyLen, salt, 8, PKCS5_ITERATIONS, EVP_aes_256_cbc(), ctx->key)) { /* Error handling */ }

    free(salt);
}

void aes256Encrypt(AES256Context* ctx, unsigned char *plaintext, int plaintextLen, unsigned char *ciphertext) {
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) { /* Error handling */ }

    int len;
    if(!EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintextLen)) { /* Error handling */ }
}
``` 
