class MyHashTable {
private:
  static const int TABLE_SIZE = 100;
  struct Entry {
    int key;
    int value;
    Entry* next;
  };
  Entry** table;

public:
  MyHashTable() {
    table = new Entry*[TABLE_SIZE](); // () initializes to nullptr
  }

  ~MyHashTable() {
    for(int i = 0; i < TABLE_SIZE; ++i) {
      while(table[i]) {
        Entry *temp = table[i]->next;
        delete table[i];
        table[i] = temp;
      }
