```c
#include <stdio.h>
#include <getopt.h>

void print_usage() {
    printf("Usage: ./a.out [OPTION]... [FILE]\n");
}

int main(int argc, char *argv[]) {
    int option = 0;
    static struct option long_options[] = {
        {"manpage", no_argument, 0, 'm'},
        {"cs", required_argument, 0, 'c'},
        {"output", required_argument, 0, 'o'},
        {0, 0, 0, 0}
    };

    while ((option = getopt_long(argc, argv, "m:c:o:", long_options, NULL)) != -1) {
        switch (option) {
            case 'm':
                printf("Manpage option\n");
                break;
            case 'c':
                printf("CS option with argument '%s'\n", optarg);
                break;
            case 'o':
                printf("Output file option with argument '%s'\n", optarg);
                break;
            default:
                print_usage();
                return 1;
        }
    }

    if (optind >= argc) {
        print_usage();
        return 1;
    }

    char *filename = argv[optind];
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    int lines = 0;
    int ch;
    while ((ch = fgetc(file)) != EOF) {
        if (ch == '\n') ++lines;
    }
    fclose(file);

    printf("Number of lines in file: %d\n", lines);

    return 0;
}
```
This C program reads command-line arguments and handles --manpage, -cs, and -o output_file options. If no input file is provided or the file cannot be opened, it prints usage information. Otherwise, it counts the number of lines in the file and outputs the count. 

