        std::unordered_map<std::string, std::string> data;
        bool online = false;
        std::shared_timed_mutex mtx;
    };

    std::vector<Node> nodes;
    size_t hash(const std::string& key) const { /* your hashing logic here */ }
    Node& locate_node(const std::string& key) const { return nodes[hash(key) % nodes.size()]; }

public:
    DistributedStorage(const std::vector<std::string>& nodeHosts): nodes(nodeHosts.size()) {
        for (size_t i = 0; i < nodeHosts.size(); ++i) nodes[i].host = nodeHosts[i];
    }

    void set(const std::string& key, const std::string& value) {
        auto& node = locate_node(key);
        std::unique_lock<std::shared_timed_mutex> lock(node.mtx);
        node.data[key] = value;
    }

    std::optional<std::string> get(const std::string& key) const {
        auto& node = locate_node(key);
        std::shared_lock<std::shared_timed_mutex> lock(node.mtx);
        if (auto it = node.data.find(key); it != node.data.end()) return it->second;
        else return {};
    }

    void remove(const std::string& key) {
        auto& node = locate_node(key);
        std::unique_lock<std::shared_timed_mutex> lock(node.mtx);
        node.data.erase(key);
    }

    void sync() { /* your logic for synchronization across nodes */ }
};
```
This is a simplified version of the system you're asking for - it hashes keys to nodes, provides basic get/set operations and uses `shared_timed_mutex` to provide thread safety. 

