    private ExecutorService executorService = Executors.newFixedThreadPool(10);

    public void fetchPokemonData() throws IOException, InterruptedException {
        HttpURLConnection connection = null;
        StringBuilder content = new StringBuilder();

        try {
            URL myurl = new URL(this.url);
            connection = (HttpURLConnection) myurl.openConnection();

            // Set request method and headers
            connection.setRequestMethod("GET");
            connection.setConnectTimeout(5000);
            connection.setReadTimeout(5000);

            int status = connection.getResponseCode();
            if (status > 299) {
                System.out.println("Failed to fetch data from third-party API");
                return;
            }

            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
        } catch (IOException ex) {
            System.out.println("Error occurred while fetching data: " + ex.getMessage());
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }

        // Process the response, here we're just printing it
        System.out.println(content);
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        PokemonService service = new PokemonService();
        service.fetchPokemonData();
    }
}
