pub struct Semaphore {
    inner: tokio::sync::Semaphore,
    permits: usize,
}

impl Semaphore {
    pub fn new(permits: usize) -> Self {
        Semaphore {
            inner: tokio::sync::Semaphore::new(permits),
            permits,
        }
    }

