const crypto = require('crypto');
const { worker } = require('cluster');

if (worker) {
  // In worker process
  let seed;
  worker.on('message', msg => {
    if (msg.type === 'SEED') {
      seed = msg.data;
    } else if (msg.type === 'GET_RANDOM') {
      const random = crypto.createHash('sha256').update(seed).digest();
      process.send({ type: 'RANDOM', data: random });
    }
  });
} else {
  // In master process, create worker processes and distribute workload
  const cpus = require('os').cpus().length;
  for (let i = 0; i < cpus; i++) {
    require('cluster').fork();
  }
}
