```csharp
using Microsoft.EntityFrameworkCore;
using System;
using System.Threading.Tasks;

public class MyDbContext : DbContext
{
    // Define your models here...
}

public interface IQueryExecutor
{
    Task ExecuteAsync(Func<MyDbContext, Task> query);
}

public class QueryExecutor : IQueryExecutor
{
    private readonly IDbContextFactory<MyDbContext> _contextFactory;

    public QueryExecutor(IDbContextFactory<MyDbContext> contextFactory)
    {
        _contextFactory = contextFactory;
    }

    public async Task ExecuteAsync(Func<MyDbContext, Task> query)
    {
        using (var context = _contextFactory.CreateDbContext())
        {
            await query(context);
            await context.SaveChangesAsync();
        }
    }
}

// Usage:
public class MyService
{
    private readonly IQueryExecutor _queryExecutor;

    public MyService(IQueryExecutor queryExecutor)
    {
        _queryExecutor = queryExecutor;
    }

    public async Task ProcessDataAsync()
    {
        await _queryExecutor.ExecuteAsync(async context =>
        {
            // Use Entity Framework to execute the query
            var result = await context.MyEntities.Where(e => e.SomeCondition).ToListAsync();

            // Process the result...
        });
    }
}
```
This is a basic example of how you could start implementing your service. The `IQueryExecutor` interface abstracts away the details of creating and managing database contexts, allowing you to easily switch between different strategies in production (like pooling for efficiency or per-request for simplicity). 

Remember that this is only one part of the solution - you'd need to implement other considerations such as monitoring, error handling, security, logging etc. Also note that Entity Framework can be slow when dealing with a large number of records because it loads all data into memory before applying filtering or sorting operations. In such cases, consider using raw SQL queries or stored procedures for better performance.
