angular.module('myApp')
  .service('DialogFieldRefreshService', ['$http', '$q', '$interval', function($http, $q, $interval) {
    this.fieldNames = []; // Field names to be refreshed
    this.configSettings = {}; // Configuration settings
    this.cache = {}; // Cache for storing API responses
    this.refreshOperations = []; // Array to store ongoing refresh operations

    // Method to dynamically receive field names and configure the service
    this.configure = function(fieldNames, config) {
      this.fieldNames = fieldNames;
      this.configSettings = config || {};
    };

    // Implement strategy pattern for different types of refresh operations
    this.refreshStrategy = {
      polling: function() {
        var self = this;
        return $interval(function() {
          if (self.refreshOperations.length < 3) {
            self.executeRefreshOperation();
          }
        }, 1000);
      },
      eventDriven: function() {
        // Implement event-driven updates here
      },
    };

    this.useStrategy = function(strategyName) {
      if (this.refreshOperations.length > 0) {
        this.cancelRefresh();
      }
      this.refreshOperations = [];
      $interval.cancel(this.intervalPromise);
      this.intervalPromise = this.refreshStrategy[strategyName]();
    };

    // Method to execute a single refresh operation
    this.executeRefreshOperation = function() {
      var self = this;
      if (self.fieldNames && self.fieldNames.length > 0) {
        var promises = [];
        angular.forEach(this.fieldNames, function(name) {
          var deferred = $q.defer();
          // Make API call or fetch from cache
          $http({ method: 'GET', url: '/someUrl' + name })
            .then(function(response) {
              self.cache[name] = response;
              deferred.resolve(self.cache[name]);
            }, function() {
              // Retry after a delay if the API request fails
              $timeout(function() {
                deferred.reject();
              }, 1000);
            });
          promises.push(deferred.promise);
        });
        $q.all(promises)
          .then(function(results) {
            self.refreshOperations = [];
            // Update dialog fields with refreshed data
          })
          .catch(function() {
            // Handle errors
          });
      }
    };

    // Method to cancel ongoing refresh operations
    this.cancelRefresh = function() {
      $interval.cancel(this.intervalPromise);
      this.refreshOperations = [];
      // Revert dialog fields back to their previous state
    };
  }]);
```
This is a basic implementation and would require additional error handling, caching management, configuration settings handling etc. You'd also need to manage concurrency issues as per your use case and make sure to test thoroughly for any bugs or performance issues.
