Next, to calculate average of last two fields from text file:
```cpp
#include <iostream>
#include <fstream>
#include <sstream>

double calculateAverage(const std::string& line) {
    std::istringstream iss(line);
    double num, sum = 0.0;
    int count = 0;

    while (iss >> num) {
        if (count >= 2) 
            break;
        ++count;
        sum += num;
    }

    return sum / count;
}

int main() {
    std::ifstream infile("input.txt");
    std::string line;
    while(std::getline(infile, line)) {
        std::cout << "Average of last two fields: " 
                  << calculateAverage(line) << "\n";
    }

    return 0;
}
```
This code reads a text file line by line and calculates the average of the last two numbers in each line. The number of digits to be averaged can easily be changed by adjusting the if (count >= 2) break condition. Note that this code does not handle possible errors such as incorrect input or empty lines, which should be added for a production-quality application.
