```csharp
using System;
using System.Collections.Generic;
using System.Text;
using System.IO;
using System.Runtime.InteropServices;

public static class WebsiteManager
{
    [DllImport("msvcrt.dll", CallingConvention = CallingConvention.Cdecl)]
    private static extern int vsprintf(StringBuilder buffer, string format, IntPtr arg);

    public static void LogErrorMessage(string message, params object[] args)
    {
        StringBuilder sb = new StringBuilder();
        IntPtr ptrArgs = Marshal.AllocHGlobal(Marshal.SizeOf<IntPtr>() * args.Length);

        try
        {
            // Copy arguments to unmanaged memory and get pointers
            Span<IntPtr> argPointers = new Span<IntPtr>((void*)ptrArgs, args.Length);
            for (int i = 0; i < args.Length; i++)
                argPointers[i] = Marshal.StringToHGlobalAnsi(args[i].ToString());

            // Format message using vsprintf
            int bufferSize = vsprintf(sb, message, ptrArgs);
            sb.Capacity = bufferSize + 1;  // +1 for null-terminator

            // Read formatted string from unmanaged memory to managed StringBuilder
            vsprintf(sb, message, ptrArgs);
        }
        finally
        {
            // Free allocated unmanaged memory
            Marshal.FreeHGlobal(ptrArgs);
        }

        // Log the formatted string here
        Console.WriteLine(sb.ToString());  // replace with actual logging mechanism
    }

    // Implement WebsiteManager methods here
}
