public class SecureStringProcessor {
    private readonly Aes _aesAlgorithm;
    private readonly HashAlgorithm _hashAlgorithm;

    public SecureStringProcessor() {
        _aesAlgorithm = Aes.Create(); // or new AesCryptoServiceProvider() in .NET Core
        _hashAlgorithm = MD5.Create(); // or new MD5CryptoServiceProvider() in .NET Core
    }

    public string CalculateHash(string input) {
        byte[] inputBytes = Encoding.ASCII.GetBytes(input);
        byte[] hashBytes = _hashAlgorithm.ComputeHash(inputBytes);

        StringBuilder sb = new StringBuilder();
        foreach (byte b in hashBytes) 
            sb.Append(b.ToString("X2")); // convert to hexadecimal

        return sb.ToString();
    }

