```python
import paho.mqtt.client as mqtt
import asyncio
from kafka import KafkaProducer
from confluent_kafka import Producer

class MessagingPlatform:
    def __init__(self):
        self.MQTT = MQTTBroker()
        self.Kafka = KafkaBroker()
        # Add more brokers here...

        self.retry_delay = 1  # Initial delay for exponential backoff
        self.max_retries = 5  # Maximum number of retries

    async def send(self, topic, message):
        tasks = []
        for broker in [self.MQTT, self.Kafka]:
            task = asyncio.create_task(broker.send(topic, message))
            tasks.append(task)

        done, _ = await asyncio.wait(tasks)
        results = [task.result() for task in done]

        # Check if any of the broker send operations failed
        for result in results:
            if not result['success']:
                print(f"Failed to send message to {result['broker']}")

    def receive(self, topic):
        pass  # Implement this based on your requirements

class MQTTBroker:
    def __init__(self):
        self.client = mqtt.Client()

    async def send(self, topic, message):
        for i in range(messaging_platform.max_retries):
            try:
                self.client.connect("localhost", 1883, 60)
                self.client.publish(topic, message);
                return {'success': True, 'broker': 'MQTT'}
            except Exception as e:
                print(f"Failed to send MQTT message: {e}")
                await asyncio.sleep(messaging_platform.retry_delay)
                messaging_platform.retry_delay *= 2  # Exponential backoff

        return {'success': False, 'broker': 'MQTT'}

class KafkaBroker:
    def __init__(self):
        self.producer = KafkaProducer(bootstrap_servers='localhost:9092')

    async def send(self, topic, message):
        for i in range(messaging_platform.max_retries):
            try:
                future = self.producer.send(topic, message)
                _ = future.get(timeout=10)  # Wait until the message is sent (sync send)
                return {'success': True, 'broker': 'Kafka'}
            except Exception as e:
                print(f"Failed to send Kafka message: {e}")
                await asyncio.sleep(messaging_platform.retry_delay)
                messaging_platform.retry_delay *= 2  # Exponential backoff

        return {'success': False, 'broker': 'Kafka'}
```
This is a simple asynchronous implementation that sends messages to both MQTT and Kafka brokers using the respective Python client libraries. It retries sending the message if it fails due to a transient failure, with an exponential backoff delay between each retry. 

Please note: This code only implements basic error handling and recovery mechanisms for transient failures. To fully meet all requirements of production-level messaging platform, additional considerations such as monitoring, alerting, failover mechanisms, logging, security measures, data persistence, scalability etc., need to be implemented as well.
']

