```c
#include <openssl/evp.h>
#include <argon2.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>

// Global mutex to ensure thread-safe operations 
pthread_mutex_t lock;

typedef struct {
    unsigned char* salt;
    int iterations, memoryCost, parallelism, cpuCost;
} KeyDerivationParams;

KeyDerivationParams getKeyDerivationParamsFromConfigService() {
    // Code to retrieve key derivation parameters from external service goes here.
}

unsigned char* deriveKey(char* password) {
    KeyDerivationParams params = getKeyDerivationParamsFromConfigService();

    unsigned char* derived_key = malloc(32); // Allocate space for the derived key 
    argon2i_hash_raw(params.iterations, params.memoryCost, params.parallelism, password, strlen(password), params.salt, 16, derived_key, 32);

    return derived_key;
}

void* encrypt(void* arg) {
    char* data = (char*)arg; // Data to be encrypted
    unsigned char* key = deriveKey("password"); // This should be retrieved from a secure storage, like a configuration service or environment variable

    EVP_CIPHER_CTX *ctx;
    int len;
    unsigned char ciphertext[128];

    pthread_mutex_lock(&lock); // Lock the mutex to ensure thread safety 

    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, EVP_aes_256_cbc(), key, NULL);
    EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char*)data, strlen(data));

    // Code to handle encrypted data and errors goes here. 

    pthread_mutex_unlock(&lock); // Unlock the mutex once done
}

void* decrypt(void* arg) {
    unsigned char* ciphertext = (unsigned char*)arg; // Cipher text to be decrypted
    unsigned char* key = deriveKey("password"); 

    EVP_CIPHER_CTX *ctx;
