```cpp
#include <forward_list>
#include <functional>
#include <iostream>

class IntegerManager {
public:
    using Comparator = std::function<bool(int)>;

    IntegerManager() : list_{}, comparator_{[](int){ return false; }} {}

    void insert_after(const int target, const int newValue, Comparator comp = {}) {
        if (comp == nullptr) 
            comp = [](int){ return true; }; // default to checking equality

        for(auto it=list_.begin(); it != list_.end(); ++it) {
            if(*it == target && comp(target)) {
                list_.insert_after(it, newValue);
                return;
            }
        }
        // no match found, appending at end
        list_.push_front(newValue); 
    }

private:
    std::forward_list<int> list_;
    Comparator comparator_;
};

// Test for the IntegerManager class
void test() {
    IntegerManager im;
    // Tests insert_after with default equality check
    im.insert_after(1, 2);
    im.insert_after(3, 4);

    // Tests insert_after with custom comparator function
    auto comp = [](int val){ return val == 3; };
    im.insert_after(5, 6, comp);
}
```
