// Import necessary dependencies
import com.rabbitmq.client.Channel;
import com.rabbitmq.client.Connection;
import com.rabbitmq.client.ConnectionFactory;
import org.springframework.amqp.core.Queue;
import org.springframework.amqp.rabbit.annotation.RabbitListener;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.web.bind.annotation.*;

@SpringBootApplication
@RestController
public class Application {

    public static void main(String[] args) throws Exception {
        SpringApplication.run(Application.class, args);
    }

    @Bean
    Queue queue() {
        return new Queue("SampleQueue", false);
    }

    @PostMapping("/send")
    public String sendMessage(@RequestBody String message) throws Exception {
        ConnectionFactory factory = new ConnectionFactory();
        factory.setHost("localhost");
        try (Connection connection = factory.newConnection();
             Channel channel = connection.createChannel()) {
            channel.queueDeclare(queue().getName(), false, false, false, null);
            channel.basicPublish("", queue().getName(), null, message.getBytes());
            return "Message sent: " + message;
        }
    }

    @RabbitListener(queues = "SampleQueue")
    public void listen(String in) {
        System.out.println("Received: " + in);
    }
}
```

This is a basic setup for RabbitMQ and Spring Boot, it doesn't cover the full scope of your requirements like real-time analytics, handling large scale logs, integrating with third-party tools or implementing end to end encryption. But it should give you an idea about how to get started.
