To implement the AES-256-CBC library you can use the `AesCryptoServiceProvider` class from .NET Framework which is part of System.Security.Cryptography namespace:

```csharp
public class Aes256CbcLib
{
    private readonly IAuthenticationService _authenticationService;

    public Aes256CbcLib(IAuthenticationService authenticationService)
    {
        _authenticationService = authenticationService;
    }

    public byte[] Encrypt(byte[] plaintext, string password)
    {
        // Use the derived key from password and IV to encrypt plain text.
        using (AesCryptoServiceProvider aesAlg = new AesCryptoServiceProvider())
        {
            aesAlg.Key = _authenticationService.DeriveKeyFromPassword(password);
            aesAlg.IV = _authenticationService.DeriveIvFromPassword(password);

            ICryptoTransform encryptor = aesAlg.CreateEncryptor(aesAlg.Key, aesAlg.IV);
            return PerformCryptography(plaintext, encryptor);
        }
    }

    private byte[] PerformCryptography(byte[] data, ICryptoTransform cryptoTransformer) 
    {
        using (MemoryStream ms = new MemoryStream())
        {
            using (CryptoStream cs = new CryptoStream(ms, cryptoTransformer, CryptoStreamMode.Write))
            {
                cs.Write(data, 0, data.Length);
            }

            return ms.ToArray();
        }
    }
}
```
