// Cache to store processed files for reuse, size based on your memory capacity.
let cache = new LRU({ max: 100 });

function processFile(filePath, callback) {
    fs.readFile(filePath, 'utf8', (err, data) => {
        if (err) return callback(err);
        let result;

        // Parse the file and do whatever processing is needed here...
        try{
            switch (path.extname(filePath)) {
                case '.json': 
                    result = JSON.parse(data);
                    break;
                case '.csv':
                    result = parseCSV(data); // Some function to parse CSV data.
                    break;
                // More file types can be added here...
            }
        } catch (error) {
            return callback(error);
        }

        cache.set(filePath, result);  // Cache the processed data for reuse.
        callback(null, result);
    });
}

const queue = async.queue((task, callback) => {
    processFile(task.path, (err, res) => {
        if (err) return callback(err);  // Error handling here...

        axios.post('http://external-api', res)  // Post processed data to external API endpoint.
            .then(() => callback())   // Callback after successful post.
            .catch((error) => callback(error)); // Handle error from the external API.
    });
}, 100);   // Process up to 100 files simultaneously.

fs.watch('your-dir', (eventType, filename) => {
    if (filename && path.extname(filename)) {
        const filePath = path.join('your-dir', filename);

        if (!cache.has(filePath)){  // Only process the file if it's not already in the cache.
            queue.push({path: filePath}, (err) => {
                if (err) console.log(err);   // Error handling here...
            });
        }
    }
});
