```cpp
// Dependencies
#include <thread>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <chrono>
#include <iostream>

class Order {
    // Contains order details
};

class PaymentGateway {
    public:
        bool processPayment(Order o) {
            // Implement payment processing logic here. In case of failure, return false
        }
};

class InventoryService {
    public:
        void updateInventory(Order o) {
            // Implement inventory updating logic here
        }
};

class CustomerDatabase {
    public:
        void updateCustomerInfo(Order o) {
            // Implement customer info updating logic here
        }
};

// Thread-safe queue for orders
class OrderQueue {
    std::queue<Order> orders;
    std::mutex mtx;
    std::condition_variable cv;
public:
    void push(Order o) {
        std::lock_guard<std::mutex> lock(mtx);
        orders.push(o);
        cv.notify_all();
    }

    Order pop() {
        std::unique_lock<std::mutex> lock(mtx);
        while (orders.empty()) {
            cv.wait(lock);
        }
        Order o = orders.front();
        orders.pop();
        return o;
    }
};

// Worker thread that processes orders
class ProcessOrderThread {
public:
    void operator()() {
        PaymentGateway pg;
        InventoryService is;
        CustomerDatabase cd;

        while (true) {
            Order o = orderQueue.pop();

            if (!pg.processPayment(o)) {
                // Handle payment failure
                continue;
            }

            is.updateInventory(o);
            cd.updateCustomerInfo(o);
        }
    }
};

// Main service class
class batchProcessOrders {
public:
    batchProcessOrders() : numThreads(std::thread::hardware_concurrency()) {
        // Start worker threads
        for (int i = 0; i < numThreads; ++i) {
            std::thread t(ProcessOrderThread());
            t.detach();  // Detach the thread so it can run independently
        }
    }

    void addOrder(Order o) {
        orderQueue.push(o);
    }
private:
    OrderQueue orderQueue;
    const int numThreads;
};
```
This is a high-level overview and does not cover all the details mentioned in your constraints. You will need to implement these features yourself, including error handling, logging, resource management, notification systems, etc. Also, it's important to remember that writing such a complex system requires strong expertise in concurrency control, network programming, performance optimization, and more.
