    struct State *next;
} State;

State* mergeStates(char **fsaUrls, int fsaCount) {
    // Handle edge case of no FSAs
    if (fsaCount == 0) return NULL;

    pthread_t threads[fsaCount];
    char *states[fsaCount];
    for(int i = 0; i < fsaCount; i++){
        // Create a new thread to fetch FSA data, pass URL and array index as arguments
        if(pthread_create(&threads[i], NULL, fetchFSAData, &(struct ThreadArgs) {fsaUrls[i], i, states}) != 0){
            fprintf(stderr, "Failed to create thread: %s\n", strerror(errno));
            return NULL;
        }
    }

    // Wait for all threads to finish their work
    for(int i = 0; i < fsaCount; i++){
        if(pthread_join(threads[i], NULL) != 0){
            fprintf(stderr, "Failed to join thread: %s\n", strerror(errno));
            return NULL;
        }
    }

    // Merge all states into a single list
    State *head = NULL;
    State *tail = NULL;
    for(int i = 0; i < fsaCount; i++){
        if(!states[i]) continue;  // Skip if fetch failed

        State *newState = malloc(sizeof(State));
        newState->name = strdup(states[i]);
        free(states[i]);
        newState->next = NULL;

        if(!head){  // First state
            head = tail = newState;
        } else {
            tail->next = newState;
            tail = newState;
        }
    }

    return head;
}

struct ThreadArgs{
    char *url;
    int index;
    char **states;
};

void* fetchFSAData(void *arg){
    struct ThreadArgs *threadArgs = (struct ThreadArgs*) arg;

    CURL *curl = curl_easy_init();
    if(!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return NULL;
    }

    curl_easy_setopt(curl, CURLOPT_URL, threadArgs->url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &threadArgs->states[threadArgs->index]);

    // Perform the request and check for errors
    if (curl_easy_perform(curl) != CURLE_OK){
        fprintf(stderr, "Failed to fetch FSA data: %s\n", curl_easy_strerror(res));
        return NULL;
    }

    // Cleanup
    curl_easy_cleanup(curl);
}

size_t writeCallback(void *contents, size_t size, size_t nmemb, void *userp){
    size_t realsize = size * nmemb;
    char *data = (char*) userp;

    // Allocate memory for new data and append it to existing data
    char *newData = malloc(strlen(data) + realsize + 1);
    strcpy(newData, data);
    strncat(newData, contents, realsize);

