class ConnectionManager {
private:
    std::unordered_map<std::string, Connection*> connections;
    std::mutex mtx;

public:
    void AddConnection(const std::string& id, const Connection& conn) {
        // Acquire lock
        std::lock_guard<std::mutex> lck(mtx);

        // Add connection to map 
        connections[id] = new Connection(conn);
    }

    void UpdateConnection(const std::string& id, const Connection& conn) {
        // Acquire lock
        std::lock_guard<std::mutex> lck(mtx);

        // Check if connection exists before updating
        if (connections.find(id) != connections.end()) {
            *connections[id] = conn;
        } else {
            throw std::runtime_error("Connection not found");
        }
    }

    void RemoveConnection(const std::string& id) {
        // Acquire lock
        std::lock_guard<std::mutex> lck(mtx);

        // Check if connection exists before removing
        if (connections.find(id) != connections.end()) {
            delete connections[id];
            connections.erase(id);
        } else {
            throw std::runtime_error("Connection not found");
        }
    }

    //...Other methods...
};

