use std::thread;
use std::sync::{Arc, Mutex};
use std::sync::mpsc;

struct Worker {
    id: usize,
    receiver: mpsc::Receiver<Box<dyn Fn()>>,
}
impl Worker {
    fn new(id: usize, receiver: mpsc::Receiver<Box<dyn Fn()>>) -> Worker {
        let worker = Worker { id, receiver };
        let handle = thread::spawn(move || {
            loop {
                match worker.receiver.recv() {
                    Ok(job) => job(),
                    Err(_) => break,
                }
            }
        });
        drop(handle);
        worker
    }
}
