import java.io.*;
import java.nio.file.*;
import java.security.*;

public class DeserializationService {
    private final ClassLoader customClassLoader;

    public DeserializationService(URL[] externalUrls) throws MalformedURLException {
        URLClassLoader urlClassLoader = new URLClassLoader(externalUrls, getClass().getClassLoader());
        SecurityManager sm = System.getSecurityManager();
        if (sm != null) {
            sm.checkPermission(new RuntimePermission("setContextClassLoader"));
        }
        Thread.currentThread().setContextClassLoader(urlClassLoader);
        this.customClassLoader = urlClassLoader;
    }

    public Object deserializeFromBytes(byte[] bytes) throws ClassNotFoundException, IOException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
             ObjectInput in = new ObjectInputStream(bais)) {
            return in.readObject();
        } catch (ClassNotFoundException | IOException e) {
            throw e;
        }
    }

    public Object deserializeFromFile(String filePath, String className) throws ClassNotFoundException, IOException {
        byte[] bytes = Files.readAllBytes(Paths.get(filePath));
        return customClassLoader.loadClass(className).cast(deserializeFromBytes(bytes));
    }
}
```
This example only demonstrates deserialization from bytes and files using a custom class loader to handle external dependencies, and does not address network failures, concurrency-safe operations, or caching strategies for data schema changes. 

