const stateMachine = {
    states: {},
    currentState: null,

    register(state) {
        this.states[state.name] = state;
    },

    transitionTo(newStateName) {
        return new Promise((resolve, reject) => {
            if (!this.currentState) {
                this.currentState = this.states[newStateName];
                resolve();
            } else if (this.states[newStateName].index > this.currentState.index) {
                this.currentState = this.states[newStateName];
                resolve();
            } else {
                reject(new Error('Cannot transition to a state with lower index'));
            }
        });
    },
};
