    char buffer[4096];
    std::shared_mutex mutex;

public:

    DistributedHashTable() : sock(service), curl(curl_easy_init()), hashMap(), nodes() {}

    ~DistributedHashTable() { 
        for (auto &node : nodes) delete node; 
        curl_easy_cleanup(curl); 
    }

    void addNode(const std::string& address, const std::string& port) {
        nodes.push_back(new Node(address, port));
    }

