class MemoryManager:
    def __init__(self):
        self.memory_pool = []  # Acts as a dynamic pool of memory blocks

    def allocate(self, size):
        for block in self.memory_pool:
            if block['size'] >= size and not block['used']:
                block['used'] = True
                return block['address']
        new_block = {'address': malloc(size), 'size': size, 'used': True}  # Allocates a new memory block using C's malloc() function.
        self.memory_pool.append(new_block)
        return new_block['address']

    def deallocate(self, address):
        for block in self.memory_pool:
            if block['address'] == address:
                block['used'] = False
