size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char*)userp)[nmemb] = 0;
}

int main() {
    CURL* curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return 1;
    }

    char url[] = "https://api.example.com/v1/resource";
    char response[CURL_MAX_WRITE_SIZE];
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, response);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to perform request: %s\n", curl_easy_strerror(res));
        return 1;
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code != 200) {
        fprintf(stderr, "Failed to get resource: HTTP code %ld\n", http_code);
        return 1;
    }

    curl_easy_cleanup(curl);

    printf("Response: %s\n", response);
    return 0;
}
```
