const fetch = require('node-fetch');

async function copyBytesFromBuffer(url, startIndex, numOfBytes) {
    try {
        const response = await fetch(url);

        if (response.ok) {
            const buffer = Buffer.from(await response.arrayBuffer());

            // Create a new buffer with specified number of bytes starting from startIndex
            const copiedData = buffer.subarray(startIndex, startIndex + numOfBytes);

            return copiedData;
        } else {
            throw new Error(`Server responded with status: ${response.status} (${response.statusText})`);
        }
    } catch (err) {
