```javascript
const axios = require('axios');
const fs = require('fs').promises;
const path = require('path');
const util = require('util');
const setTimeoutPromise = util.promisify(setTimeout);

let extensionsCache = null;
async function getSupportedExtensions() {
    if (!extensionsCache) {
        try {
            const res = await axios.get('https://third-party-api/supported_formats'); // replace with your actual API endpoint
            extensionsCache = res.data;
        } catch (err) {
            console.error(`Error fetching supported formats: ${err}`);
            throw err;
        }
    }
    return extensionsCache;
}

async function readFile(filePath) {
    try {
        const data = await fs.readFile(filePath, 'utf8');
        return data;
    } catch (err) {
        console.error(`Error reading file ${filePath}: ${err}`);
        throw err;
    }
}

async function checkDirectory() {
    const supportedExtensions = await getSupportedExtensions();
    const dirFiles = await fs.readdir('./directory'); // replace with your directory path
    for (const file of dirFiles) {
        if (supportedExtensions.includes(path.extname(file))) {
            const content = await readFile(`./directory/${file}`);
            console.log(content);
        }
    }
}

async function checkDirectoryPeriodically() {
    while (true) {
        try {
            await checkDirectory();
            await setTimeoutPromise(5000); // wait for 5 seconds
        } catch (err) {
            console.error('Error checking directory:', err);
            await setTimeoutPromise(60000); // wait for a minute before trying again
        }
    }
}

checkDirectoryPeriodically();
```

This script periodically checks the specified directory, and if any new files with supported extensions are found, it asynchronously reads their contents into memory. Please replace `'https://third-party-api/supported_formats'` and `'./directory'` with your actual API endpoint URL and directory path respectively.

