2. Create a simple Rust file (e.g., main.rs) with the following code:

```rust
use clap::Parser;
use indicatif::{ProgressBar, ProgressStyle};
use std::process::Command;
use std::time::Instant;

#[derive(Parser, Debug)]
#[clap(author, version, about, long_about = None)]
struct Args {
    #[clap(short, long)]
    path: String,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();
    compile_with_metrics(&args.path)?;

    Ok(())
}

fn compile_with_metrics(path: &str) -> Result<(), Box<dyn std::error::Error>> {
    let bar = ProgressBar::new(100);

    // Start the progress bar with a message.
    bar.set_message("Compiling Rust code...");

    let start = Instant::now();

    for i in 0..10 {
        bar.set_position((i+1)*10);
        std::thread::sleep(std::time::Duration::from_millis(500));
    }

    let output = Command::new("rustc")
        .arg(path)
        .output()?;

    if !output.status.success() {
        printlnmacroexpand1234567890!");
        panicmacroexpand1234567890!"Compilation failed!");
    }

    let duration = start.elapsed();
    printlnmacroexpand1234567890!"Compilation took: {:.2?}", duration);

    bar.finish_with_message("Compilation completed");

    Ok(())
}
```

This is a very basic CLI tool that takes the path to the Rust file as an argument, compiles it using `rustc` command and measures the time taken for compilation with progress bar. Note that error handling has been kept minimal and this doesn't cover all your requirements such as managing third-party libraries or implementing a cache system etc.
