    public MigrationService(IExternalDataSource externalDataSource, 
                            IDestinationRepository destinationRepository, 
                            ISecurityService securityService, 
                            IMonitoringService monitoringService)
    {
        _externalDataSource = externalDataSource;
        _destinationRepository = destinationRepository;
        _securityService = securityService;
        _monitoringService = monitoringService;
    }

    public async Task MigrateUserData()
    {
        // Fetch data from external source, e.g., API call
        var data = await _externalDataSource.GetUserDataAsync();

        // Encrypt sensitive data before storing it in the destination repository
        var encryptedData = _securityService.EncryptSensitiveData(data);

        // Start migration tasks for each piece of data 
        var migrationTasks = new List<Task>();
        foreach (var item in encryptedData)
        {
            var task = _destinationRepository.StoreUserDataAsync(item);
            migrationTasks.Add(task);
        }

        // Wait for all tasks to complete, log any exceptions and continue
        try
        {
            await Task.WhenAll(migrationTasks);
        }
        catch (Exception ex) when (ex is AggregateException aggregateEx && 
                                   aggregateEx.InnerExceptions.Any())
        {
            foreach (var innerException in aggregateEx.InnerExceptions)
            {
                _monitoringService.LogError(innerException);
            }
        }

        // Report the migration status to external monitoring service
        var status = new MigrationStatus{ /* populate with relevant info */ };
        await _monitoringService.ReportMigrationStatusAsync(status);
    }
}
