```csharp
public class DataIngestionPipeline 
{
    private ConcurrentDictionary<string, Task> _tasks; // Dictionary to hold tasks for each source
    private CancellationTokenSource _tokenSource; // Token to cancel all running tasks

    public DataIngestionPipeline() 
    {
        _tasks = new ConcurrentDictionary<string, Task>();
        _tokenSource = new CancellationTokenSource();
    }

    public void Start(IEnumerable<IDataSource> sources) 
    {
        foreach (var source in sources) 
        {
            var task = ProcessDataAsync(source, _tokenSource.Token);
            _tasks[source.Id] = task;
        }
    }

    public async Task ProcessDataAsync(IDataSource source, CancellationToken token) 
    {
        while (!token.IsCancellationRequested) 
        {
            // Connect to data source
            using var connection = await source.ConnectAsync();

            // Read and process data stream in chunks
            await foreach (var chunk in connection.ReadDataStream()) 
            {
                // Process each chunk of data asynchronously, e.g.,
                _ = Task.Run(async () => 
                {
                    using var dbConnection = await DatabaseManager.GetConnectionAsync();

                    // Insert or update data in database
                    await dbConnection.InsertOrUpdateDataAsync(chunk);
                });
            }
        }
    }

    public void Stop() 
    {
        _tokenSource.Cancel();

        Task.WaitAll(_tasks.Values.ToArray()); // Wait for all tasks to finish
    }
}
```

This is a high-level design and does not take into account all the complexities of your problem such as error handling, schema changes, multi-tenancy, resource contention, data validation/compression, resilience mechanisms, etc. Also it doesn't provide specific implementations for external metadata service or schema resolution mechanism which would require significant additional complexity and time to design and implement properly.
