    {
        string requestBody = await new StreamReader(req.Body).ReadToEndAsync();
        dynamic data = JsonConvert.DeserializeObject(requestBody);

        if (data?.userInput == null)
            return new BadRequestObjectResult("Please pass a user input in the request body");

        using var sha256 = SHA256.Create();
        byte[] hashedBytes = 
            sha256.ComputeHash(Encoding.UTF8.GetBytes((string)data?.userInput));

        string hashString = BitConverter.ToString(hashedBytes).Replace("-", "").ToLower();

        Document document = new Document { id = Guid.NewGuid().ToString(), UserInput = (string)data?.userInput, HashValue = hashString };

        await _cosmosDbClient.CreateDocumentAsync(UriFactory.CreateDocumentCollectionUri("your-database", "your-collection"), document);

        return new OkObjectResult(hashString);
    }

    public class Document {
        public string id { get; set; }
        public string UserInput { get; set; }
        public string HashValue { get; set; }
    }
}
```
