```cpp
#include <grpc++/grpc++.h>
#include <unordered_map>
#include "kvstore.grpc.pb.h" // Assuming protobuf definitions

class KVStoreServiceImpl final : public KVStore::Service {
  std::unordered_map<std::string, std::string> store;

  grpc::Status Get(grpc::ServerContext* context, const GetRequest* request,
                   GetResponse* response) override {
    auto key = request->key();
    if (store.find(key) != store.end()) {
      response->set_value(store[key]);
      return grpc::Status::OK;
    } else {
      return grpc::Status(grpc::NOT_FOUND, "Key not found");
    }
  }

  grpc::Status Set(grpc::ServerContext* context, const SetRequest* request,
                   SetResponse* response) override {
    store[request->key()] = request->value();
    return grpc::Status::OK;
  }
};

int main() {
  std::string server_address("0.0.0.0:50051");
  KVStoreServiceImpl service;

  grpc::ServerBuilder builder;
  builder.AddListeningPort(server_address, grpc::InsecureServerCredentials());
  builder.RegisterService(&service);
  std::unique_ptr<grpc::Server> server(builder.BuildAndStart());

  // ... handle signals and wait for shutdown ...
}
```

