typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next, *prev;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int currentSize = 0;
int maxSize; // Set by user at initialization

// Function to create and manage a dynamically sized linked list of NFAPI_CRC_INDICATION_PDU_T structures.
Node* CreateAndManageList(NFAPI_CRC_INDICATION_PDU_T data, int operation) {
    pthread_mutex_lock(&lock); // Lock to prevent concurrent access issues
    Node *newNode = (Node*) malloc(sizeof(Node));

    if (!newNode) {
        return NULL;  // Handle memory allocation failure.
    }

    newNode->data = data;
    newNode->next = head;

    switch (operation){
        case INSERT:
            if(currentSize < maxSize){
                if (head != NULL) {
                    head->prev = newNode; 
                }

                head = newNode;
                currentSize++; // Track current size of list.
            } else {
                free(newNode);
                return NULL; // Handle case where max size reached.
            }
            break;
        case DELETE:
            Node *temp = head;

            while (temp != NULL) {
                if (temp->data.RNTI == data.RNTI) { 
                    if(temp->prev != NULL){
                        temp->prev->next = temp->next;
                    } else {
                        head = temp->next;
                    }

                    free(temp);
                    currentSize--; // Reduce size when deleting.
                    break;
                }

                temp = temp->next; 
            }
            break;
        default:
            assert(0 && "Invalid operation");
    }

    pthread_mutex_unlock(&lock); // Unlock to allow other threads to access.
    return newNode;
}
```
