typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[50];  //Assuming it's a string of length less than or equal to 50.
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    int key;
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node *next, *prev;
} Node;

Node* head = NULL;
pthread_mutex_t lock;

void* addToList(int key, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&lock);

    Node *node = (Node*) malloc(sizeof(Node));
    node->data = data;
    node->key = key;
    node->next = head;
    if (head != NULL) {
        head->prev = node;
    }

    head = node;
    pthread_mutex_unlock(&lock);
}
```
