```javascript
// Import required libraries
const express = require('express');
const https = require('https');
const fs = require('fs');
const app = express();
app.use(express.json());

// Load certificates for mutual TLS
var options = {
    key: fs.readFileSync('client-key.pem'),
    cert: fs.readFileSync('client-cert.pem'),

    // This is necessary only if the server uses the
    // self-signed certificate
    rejectUnauthorized: false,
};

// Function to send GET request to IoT device API
async function getDataFromDevice(deviceApiUrl, token) {
    return new Promise((resolve, reject) => {
        const req = https.get({
            hostname: deviceApiUrl,
            path: '/data',
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${token}`
            },
            agent: new https.Agent(options) // for mutual TLS
        }, (res) => {
            let data = '';

            res.on('data', (chunk) => {
                data += chunk;
            });

            res.on('end', () => {
                resolve(JSON.parse(data));
            });
        });

        req.on('error', (e) => {
            reject(e);
        });
    });
}

// Endpoint to receive data from devices
app.post('/receiveData', async (req, res) => {
    try{
        const deviceApiUrl = req.body.deviceApiUrl;
        const token = req.body.token;

        // Get data from IoT device API
        const result = await getDataFromDevice(deviceApiUrl, token);

        // Process the data according to your requirements

        res.json({ success: true });
    } catch (e) {
        console.error(e);
        res.status(500).send(e.message);
    }
});

const port = process.env.PORT || 8080;
app.listen(port, () => console.log(`Server running on port ${port}`));
```
This is a simple Express server that accepts POST requests at `/receiveData` endpoint with the IoT device API URL and a token for authentication. It then sends a GET request to the IoT device's API, processes the response as per your requirements, and responds with a success message. 

