```javascript
const request = require('request-promise');
const semver = require('semver');
const LRUCache = require("lru-cache");
const cache = new LRUCache({ maxAge: 1000 * 60 * 60 }); // Cache for one hour.

class AssembleFooterScripts {
    constructor(config) {
        this.config = config;
    }

    async getScriptFromUrl(url) {
        if (cache.has(url)) return cache.get(url);

        const scriptContent = await request(url);
        cache.set(url, scriptContent);
        return scriptContent;
    }

    validateVersion(version1, version2) {
        // Use semver to validate compatibility.
        return semver.satisfies(version1, version2);
    }

    async assembleFooterScripts() {
        let scripts = [];

        for (let i = 0; i < this.config.urls.length; i++) {
            const scriptContent = await this.getScriptFromUrl(this.config.urls[i].url);

            if (!this.validateVersion(scriptContent.version, this.config.urls[i].version)) {
                console.log("Version conflict detected");
                continue;
            }

            scripts.push(scriptContent);
        }

        return scripts;
    }
}
```
This is a simple example of how you can start with your project. There are many other factors that need to be considered and added in the above code such as error handling, concurrency control, CI/CD integration etc. However, it serves as a basic starting point for your task. 

