```typescript
import { Service } from './cloudService';

interface Module {
    id: string;
    version: number;
    dependencies: Module[];
}

class ModuleLoader {
    private cloudService: Service;
    private cache = new Map<string, Promise<Module>>();
    constructor(service: Service) {
        this.cloudService = service;
    }

    async loadModule(id: string): Promise<Module> {
        if (this.cache.has(id)) {
            return this.cache.get(id);
        }

        const modulePromise = this.fetchAndExecute(id);
        this.cache.set(id, modulePromise);
        return modulePromise;
    }

    private async fetchAndExecute(id: string): Promise<Module> {
        try {
            // Fetch the module from cloud service
            const data = await this.cloudService.fetchModule(id); 

            // Create a module instance and initialize it with fetched data
            const moduleInstance = new Module();
            Object.assign(moduleInstance, data);

            for (const dependency of moduleInstance.dependencies) {
                await this.loadModule(dependency.id);
            }

            // Execute the loaded module 
            eval(moduleInstance.code);

            return moduleInstance;
        } catch (error) {
           console.log('Error loading module: ', error);
        }
    }
}
```
Please note that creating a fully-featured JavaScript/TypeScript module loader is a complex task, requiring deep knowledge of network protocols and security considerations. This basic implementation does not cover all possible edge cases and should be expanded to include these features before being used in production. 

This example also uses `eval` which should be avoided if at all possible due to potential security risks, as it can execute arbitrary code. Depending on the use case, you might want to look into other ways to execute loaded modules like Web Workers or new Function().
