    pthread_mutex_lock(&mutexPool);

    if (poolIndex >= POOL_SIZE) {
        // Allocate more records when the pool is full
        Record* newRecords = malloc(sizeof(Record) * POOL_SIZE);
        for (int i = 0; i < POOL_SIZE; i++) {
            pool[poolIndex + i] = &newRecords[i];
        }
    }

    Record* record = pool[poolIndex];
    poolIndex++;

    pthread_mutex_unlock(&mutexPool);

    return record;
}

// Memory deallocation function
