package main

import (
	"github.com/aws/aws-sdk-go/service/s3"
)

type S3Service struct {
	bucket string
	s3     *s3.S3
}

func NewS3Service(region, bucket string) (*S3Service, error) {
	sess := session.New(&aws.Config{Region: aws.String(region)})
	if _, err := sess.Config.Credentials.Get(); err != nil {
		return nil, fmt.Errorf("failed to get AWS credentials: %v", err)
	}
	s3Svc := s3.New(sess)

	// Check if the bucket exists
	if _, err := s3Svc.HeadBucket(&s3.HeadBucketInput{Bucket: aws.String(bucket)}); err != nil {
		return nil, fmt.Errorf("failed to access S3 bucket %q: %v", bucket, err)
	}

	return &S3Service{
		s3:     s3Svc,
		bucket: bucket,
	}, nil
}

func (s *S3Service) Put(key string, data []byte) error {
	_, err := s.s3.PutObject(&s3.PutObjectInput{
		Body:   bytes.NewReader(data),
		Bucket: aws.String(s.bucket),
		Key:    aws.String(key),
	})
	return err
}
```
This is a very basic example and does not include all the features you requested, but it should give you an idea of how to start with AWS S3 in Go. For multi-cloud support, you would need similar structs for Google Cloud Storage or Azure Blob Storage, each with their own Put method which handles the specific cloud provider's API. 

