    // Run the Rust compiler as a subprocess. 
    catch_with_exit_code(|| {
        Command::new("rustc")
            .arg(path)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()?;

