import java.util.*;
import org.apache.commons.lang3.concurrent.ConcurrentException;

public class DistributedCacheService {
    // Cache data structure
    private Map<String, CacheItem> cache = new ConcurrentHashMap<>();
    private MonitoringPlatform monitoringPlatform1;
    private MonitoringPlatform monitoringPlatform2;
    private MonitoringPlatform monitoringPlatform3;
    private UpstreamDataSource upstreamDataSource;

    public DistributedCacheService(MonitoringPlatform platform1, 
                                   MonitoringPlatform platform2, 
                                   MonitoringPlatform platform3, 
                                   UpstreamDataSource source) {
        this.monitoringPlatform1 = platform1;
        this.monitoringPlatform2 = platform2;
        this.monitoringPlatform3 = platform3;
        this.upstreamDataSource = source;
    }

    public Object get(String key) {
        CacheItem item = cache.get(key);

        if (item != null && !item.isExpired()) {
            monitoringPlatform1.logCacheHit();
            monitoringPlatform2.logCacheHit();
            monitoringPlatform3.logCacheHit();

            return item.getValue();
        } else {
            Object value = upstreamDataSource.get(key);
            cache.put(key, new CacheItem(value));

            monitoringPlatform1.logCacheMiss();
            monitoringPlatform2.logCacheMiss();
            monitoringPlatform3.logCacheMiss();

            return value;
        }
    }

    public void put(String key, Object value) {
        cache.put(key, new CacheItem(value));

        try {
            upstreamDataSource.update(key, value);
        } catch (ConcurrentException e) {
            // retry logic...
        }
    }

    public void delete(String key) {
        cache.remove(key);

        try {
            upstreamDataSource.delete(key);
        } catch (ConcurrentException e) {
            // retry logic...
        }
    }
}
```
