            evict();
        }
        cache.put(key, new CachedObject<>(System.currentTimeMillis(), value));
    }

    // Get method to return null if the key is not present or has expired
    public synchronized V getIfPresent(K key) {
        CachedObject<V> cached = cache.get(key);

