    private final int poolSize;
    // Other data source properties like username, password etc. go here

    private final BlockingQueue<DataSource> connectionPool;
    private final List<DataSource> usedConnections = new ArrayList<>();

    public DataSourceConnectionPool(String url, int poolSize) {
        this.url = url;
        this.poolSize = Math.max(poolSize, 1);

        connectionPool = new ArrayBlockingQueue<>(this.poolSize);

        for (int i = 0; i < this.poolSize; i++) {
            connectionPool.add(createConnection());
        }
    }

    private DataSource createConnection() {
        // Code to create a new Data Source goes here
        return null;
    }

    public synchronized DataSource getConnection() throws Exception {
        if (connectionPool.isEmpty()) {
            if (usedConnections.size() >= poolSize) {
                throw new RuntimeException("Maximum pool size reached, no available connections!");
            }

            usedConnections.add(createConnection());
        }

        DataSource connection = connectionPool.remove();
        usedConnections.add(connection);

        return connection;
    }

    public synchronized void releaseConnection(DataSource connection) {
        if (usedConnections.remove(connection)) {
            connectionPool.add(connection);
        } else {
            throw new RuntimeException("Connection not in the used connections pool!");
        }
    }
}
