```python
class OrchestratorPlatform:
    def __init__(self):
        self.cloud_providers = [] # list of cloud providers
        self.services = {} # dictionary of services and their regions

    def add_provider(self, provider):
        self.cloud_providers.append(provider)

    def deploy_service(self, service, region):
        if region not in self.services:
            self.services[region] = [service]
        else:
            self.services[region].append(service)

        # Deploy to all providers
