['Here is a basic implementation using C++11 features. Due to complexity constraints and assumptions made about specifics of the task, some parts may not fully meet all requirements:

```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <vector>
#include <queue>
#include <condition_variable>
#include <functional>
#include <unordered_map>
#include <ctime>
#include <atomic>

class CommandExecutor {
public:
    void submitCommand(std::string commandId, std::function<void()> command) {
        std::lock_guard<std::mutex> lock(m);
        commands.push(commandId);
        callbacks[commandId] = command;
        cv.notify_one();
    }

    void startExecutor() {
        running = true;
        thread = std::thread(&CommandExecutor::executorLoop, this);
    }

    void stopExecutor() {
        running = false;
        cv.notify_all();
        if(thread.joinable()) thread.join();
    }

private:
    std::queue<std::string> commands;
    std::unordered_map<std::string, std::function<void()>> callbacks;
    std::atomic_bool running{false};
    std::thread thread;
    std::mutex m;
    std::condition_variable cv;

    void executorLoop() {
        while(running) {
            std::unique_lock<std::mutex> lock(m);
            cv.wait(lock, [this]{ return !commands.empty(); });

            auto commandId = commands.front();
            commands.pop();

            if(!callbacks[commandId]) { // If command was cancelled
                continue;
            }

            lock.unlock(); // Unlock during execution to prevent blocking

            callbacks[commandId](); // Execute the command
        }
    }
};
```
This is a basic implementation of CommandExecutor that uses a thread-safe queue and condition variable for handling commands concurrently, as well as a map for storing function objects. 

A more sophisticated approach may include prioritization or load balancing of tasks across multiple threads based on the complexity or criticality of the task. This can be achieved with additional data structures or algorithmic approaches like those used in scheduling algorithms and thread pools.

Integration with an external logging service is a separate layer that would need to be implemented, potentially as a wrapper around CommandExecutor, subscribing to events from it and redirecting them to the appropriate output.

