public class UserMigrationService {
    private readonly DynamoDBContext _context;
    private readonly LegacySystemClient _legacyClient;
    private readonly CacheServerClient _cacheClient;

    public UserMigrationService(IAmazonDynamoDB client, LegacySystemClient legacyClient, CacheServerClient cacheClient) {
        _context = new DynamoDBContext(client);
        _legacyClient = legacyClient;
        _cacheClient = cacheClient;
    }

    public async Task MigrateUserData() {
        try {
            // Retrieve user data from cache server first
            var cachedUsers = await _cacheClient.GetAllAsync();

            if (cachedUsers != null) {
                // If the cache server has users, use them to migrate
                foreach(var user in cachedUsers){
                    await _context.SaveAsync(user);
                }

                return;
            } 

            // If not, fallback to legacy system
            var legacyUsers = await _legacyClient.GetAllAsync();

            if (legacyUsers != null) {
                foreach(var user in legacyUsers){
                    await _context.SaveAsync(user);
                }

                return;
            } 

            throw new Exception("Unable to retrieve user data from any source");
        } catch (Exception ex) {
            // Handle errors accordingly, such as logging and retrying
            Console.WriteLine($"Error occurred while migrating user data: {ex}");
        }
    }
}
