However, I can provide you a skeleton Go code that illustrates how you can approach the problem using goroutines for concurrency, channels to communicate between goroutines, error handling and data validation. 

```go
package main

import (
	"encoding/json"
	"fmt"
	"github.com/google/uuid"
	"time"
)

type Session struct {
	SessionID      uuid.UUID `json:"session_id"`
	UserID         uuid.UUID `json:"user_id"`
	ExpiryTime     time.Time `json:"expiry_time"`
	LastActiveTime time.Time `json:"last_active_time"`
	ResetToken     string    `json:"reset_token,omitempty"`
}

func validateSession(session Session) error {
	// Validate session_id and user_id as valid UUID strings.
	if _, err := uuid.Parse(session.SessionID.String()); err != nil {
		return fmt.Errorf("invalid session id: %v", err)
	}
	if _, err := uuid.Parse(session.UserID.String()); err != nil {
		return fmt.Errorf("invalid user id: %v", err)
	}
	// Ensure expiry_time is set within the next 24 hours.
	if session.ExpiryTime.Sub(time.Now()) > 24*time.Hour {
		return fmt.Errorf("expiry time is not within the next 24 hours")
	}
	// Confirm last_active_time is within the last 15 minutes.
	if time.Since(session.LastActiveTime) > 15*time.Minute {
		return fmt.Errorf("last active time is not within the last 15 minutes")
	}
	// Verify reset_token presence if applicable, ensuring it is non-empty.
	if session.ResetToken != "" && len(session.ResetToken) == 0 {
		return fmt.Errorf("reset token is empty")
	}
	return nil
}

func processSessionData(data []byte) error {
	var sessions []Session
	err := json.Unmarshal(data, &sessions)
	if err != nil {
		return err
	}

	for _, session := range sessions {
		err = validateSession(session)
		if err != nil {
			fmt.Println("Error validating session: ", err)
			// log error details for failed sessions
		} else {
			// Process the validated session data
			fmt.Printf("Processing session %v", session)
		}
	}
	return nil
}

func main() {
	// Simulate receiving JSON data from an external authentication service
	jsonData := []byte(`[{"session_id":"123e4567-e89b-12d3-a456-426614174000", "user_id":"123e4567-e89b-12d3-a456-426614174001", "expiry_time":"2023-12-31T23:59:59Z", "last_active_time":"2022-08-15T23:59:59Z", "reset_token":""}]`)
	processSessionData(jsonData)
}
```
