```javascript
// Required packages
const express = require('express');
const axios = require('axios');
const Redis = require('ioredis');
const OAuth2Client = require('./oauth_client'); // Implement an OAuth 2.0 client
const WebSocket = require('ws');

// Setup Express server
const app = express();
app.use(express.json());

// Initialize Redis cache
const redis = new Redis({host: 'localhost'});

// Middleware to authenticate and authorize OAuth 2.0 requests
app.use((req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (token == null) return res.sendStatus(401); // If no token, unauthorized

    OAuth2Client.verify(token).then(() => {
        next();
    }).catch((err) => {
        console.error('OAuth 2.0 Verification Error:', err);
        res.sendStatus(403); // Forbidden
    });
});

// Route to fetch user data from third-party REST API
app.get('/users/:id', async (req, res) => {
    const id = req.params.id;

    // Check Redis cache for user data
    let userData = await redis.get(`user:${id}`);

    if (!userData) {
        try {
            const response = await axios.get(`https://api.example.com/users/${id}`, {
                headers: {'Authorization': `Bearer ${token}`}, // OAuth 2.0 token
            });

            userData = response.data;

            await redis.set(`user:${id}`, JSON.stringify(userData), 'EX', 60); // Cache data for 1 minute
        } catch (err) {
            console.error('Error fetching user data:', err);
            return res.status(500).send({ error: 'Failed to fetch user data' });
        }
    } else {
        userData = JSON.parse(userData); // Convert cached data back into object
    }

    res.json(userData);
});

// Set up WebSocket server for real-time updates
const wss = new WebSocket.Server({ port: 8080 });
wss.on('connection', (ws) => {
    // Handle WebSocket messages here
});

app.listen(3000, () => console.log('Server is running on port 3000'));
```
