```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h> /* For PATH_MAX */

#define MAX_RULE_LEN 1024
#define BUFFER_SIZE 4096

typedef struct Rule {
    char *name;
    int (*handler)(char*, FILE*);
} Rule;

int parseFile(const char *inputPath, const char *outputPath, const char *rulesStr) {
    /* Implement the logic for parsing file paths across different OS */

    /* Dynamically allocate buffer */
    size_t bufferSize = BUFFER_SIZE;
    unsigned char *buffer = malloc(bufferSize);

    FILE *inputFile = fopen(inputPath, "rb");
    if (inputFile == NULL) {
        free(buffer);
        return -1;
    }

    /* Split rulesStr into individual rule strings */
    Rule rules[MAX_RULE_LEN];
    char *ruleStr = strtok(rulesStr, ",");
    int ruleCount = 0;
    while (ruleStr != NULL && ruleCount < MAX_RULE_LEN) {
        /* Parse the rule string and initialize the Rule struct */

        rules[ruleCount++] = (Rule){ .name = strdup(parsedRule.name), 
                                    .handler = parsedRule.handler };

        ruleStr = strtok(NULL, ",");
    }

    FILE *outputFile = fopen(outputPath, "wb");
    if (outputFile == NULL) {
        fclose(inputFile);
        free(buffer);
        return -1;
    }

    /* Process the file */
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, bufferSize, inputFile)) > 0) {
        for (int i = 0; i < ruleCount; ++i) {
            rules[i].handler(buffer, outputFile);
        }
    }

    /* Clean up */
    fclose(inputFile);
    fclose(outputFile);
    free(buffer);

    return 0;
}
```
This is a simplified version and doesn't cover many aspects of the task. For example, it doesn't include code for integrating with multiple external data sources or implementing auto-update mechanism, but these can be implemented in a similar fashion as parsing file paths across different OSes. Please refer to a professional developer or consider consulting with an expert on this topic.
