['This is a complex task that would require multiple files and directories, as well as extensive knowledge of C++ and databases. Here is an outline for the Octree data structure:

```cpp
#include <vector>
#include <memory>
// Assuming DB access through SQLite3 here. Replace with actual library or use a wrapper class if needed.
#include "sqlite3/sqlite3.h"

class Point {
public:
    double x, y, z; // replace these with your data type
};

class OctreeNode {
public:
    OctreeNode(Point p, int capacity) : point_(p), points_(), children_() {
        capacity_ = capacity;
    }

    bool insert(const Point& p){
        if (points_.size() < capacity_) {
            points_.push_back(p);
            return true;
        }

        // The node is full, need to create children and distribute the points. 
        // For simplicity, here we just add one point in each child:
        if (children_.empty()) {
            for (int i = 0; i < 8; ++i) {
                Point childPoint = {point_.x + i / 4, point_.y + i % 2, point_.z + i % 2}; // Replace with actual calculation
                children_.push_back(std::make_unique<OctreeNode>(childPoint, capacity_));
            }
        }

        for (auto& child : children_) {
            if (child->insert(p)) return true;
        }

        // This should never happen as long as capacity_ >= 1.
        assert(false);
    }

private:
    Point point_; 
    int capacity_; 
    std::vector<Point> points_; 
    std::vector<std::unique_ptr<OctreeNode>> children_; 
};
```
