#include <time.h>

typedef struct LTE_Uplink_Signal_Report {
    int UE_ID;
    float signal_strength;
    time_t timestamp;
} Report;

// Doubly linked list
typedef struct Node {
    Report data;
    struct Node* prev;
    struct Node* next;
}Node;

Node* head = NULL;
Node* tail = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addReport(Report report) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    pthread_mutex_lock(&mutex);
    if(head == NULL){
        head = tail = newNode;
        newNode->data = report;
        newNode->prev = NULL;
        newNode->next = NULL;
    }else{
        tail->next = newNode;
        newNode->prev = tail;
        newNode->data = report;
        newNode->next = NULL;
        tail = newNode;
    }
    pthread_mutex_unlock(&mutex);
}
```
This is just a snippet of the addReport function. Please note that this is not a fully-fledged library and does not include all the features requested (like database integration, caching mechanism or error handling). To implement these features would require a more extensive codebase and potentially additional libraries or APIs. 

