        static Logger instance;
        return instance;
    }

    void Log(const LogEntry& entry) {
        std::shared_lock<std::shared_mutex> lock{ m_logMutex };

        // Push the log entry to the queue.
        m_queue.push_back(entry);

        m_condVar.notify_all();  // Notify all waiting threads about new logs.
    }

private:
    Logger() { 
        // Start a separate thread for processing log entries.
        std::thread t{ [this] { ProcessLogs(); } };
        t.detach();
    }

    void ProcessLogs() {
        while (true) {
            std::unique_lock<std::shared_mutex> lock{ m_logMutex };

            // Wait until new logs arrive or timeout occurs.
            if (m_condVar.wait_for(lock, std::chrono::seconds(5), [this] { return !m_queue.empty(); })) {
                LogEntry entry = m_queue.front();  // Get the oldest log from the queue.
                m_queue.erase(m_queue.begin());  // Remove the log from the queue after processing it.

                lock.unlock();

                // Process the log here, for example print it to console:
                std::cout << "Log processed\n";
            } else {
                // Handle timeout scenario if needed.
                std::cout << "Timeout occurred\n";
            }
        }
    }

private:
    std::shared_mutex m_logMutex;
    std::condition_variable_any m_condVar;
    std::vector<LogEntry> m_queue;  // Use a queue to store logs.
};
