['Here's an outline of how you might implement such a system. Note that this is a high-level overview and actual implementation would involve a lot more details, including error handling, logging, unit tests, etc. Also, the below example uses simple HTTP client for REST APIs and XML serialization/deserialization which may not be sufficient or efficient in real world scenario.

```CSharp
public class MyService : IMyService
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, ApiInfo> _apiList;

    public MyService() 
    {
        _httpClient = new HttpClient();

        // Initialize APIs. In real world scenario these could be read from a config file or database.
        _apiList = new ConcurrentDictionary<string, ApiInfo>
        {
            {"API1", new ApiInfo("https://api1.com/data")},
            {"API2", new ApiInfo("https://api2.com/data")}
            // Add other APIs as needed...
        };
    }

    public async Task<Data> GetData(string filter) 
    {
        var tasks = _apiList.Values.Select(async api => await FetchAndParseXmlFromApi(api, filter)).ToArray();

        // Wait for all tasks to complete or the first one that completes successfully
        while (tasks.Any()) 
        {
            Task<Data> completedTask = await Task.WhenAny(tasks);

            if (completedTask.Status == TaskStatus.RanToCompletion) 
            {
                return completedTask.Result;
            }

            // If task failed, remove it from list and retry with next available API
            var index = Array.IndexOf(tasks, completedTask);
            tasks[index] = FetchAndParseXmlFromNextAvailableApi(_apiList.Values, filter);
        }

        throw new Exception("Failed to fetch data from all APIs.");
    }

    private async Task<Data> FetchAndParseXmlFromApi(ApiInfo api, string filter) 
    {
        try 
        {
            // Fetch XML and parse it into a Data object. You may need to adjust this based on the actual API response format.
            var xmlResponse = await _httpClient.GetStringAsync(api.BaseUrl);
            return XmlDeserializer.Deserialize<Data>(xmlResponse);
        } 
        catch (Exception ex) when (ex is HttpRequestException || ex is XmlException) 
        {
            // Handle transient errors like network issue, API rate limit, etc. by retrying the request.
            api.BackoffAndRetry();

            throw new ApiException("Failed to fetch data from API.", ex);
        }
    }

    private async Task<Data> FetchAndParseXmlFromNextAvailableApi(IEnumerable<ApiInfo> apis, string filter) 
    {
        // Implement logic to select the next available API. You could use a round-robin strategy or consider other factors like recent availability etc.

        foreach (var api in apis) 
        {
            if (!api.IsUnavailable()) 
            {
                return await FetchAndParseXmlFromApi(api, filter);
            }
        }

        throw new Exception("No available API.");
    }
}
```
This code is written in a way that it can be easily extended and maintained. For example, to support additional REST APIs or filters you just need to add them to the `_apiList` dictionary or modify the existing ones respectively. All classes are designed to be loosely coupled which means they don't depend on each other and can be easily replaced with alternative implementations.
']

