typedef struct MemoryPoolStruct {
    int size;  // Current allocated memory in the pool
    int capacity;  // Total capacity of the pool
    NFAPI_CRC_INDICATION_PDU_T* data;  // Pointer to allocated memory
} MemoryPool;

// Global mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

MemoryPool createMemoryPool(int N) {
    pthread_mutex_lock(&lock);  // Lock the mutex to avoid data races

    MemoryPool memoryPool;
    memoryPool.size = 0;
    memoryPool.capacity = N;
    memoryPool.data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));  // Allocate memory for the pool

    if (memoryPool.data == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_unlock(&lock);  // Unlock the mutex after allocation

    return memoryPool;
}
