use std::time::{Duration, Instant};
use std::process::Command;
use rustc_driver::catch_with_exit_code;
use rusage::*;

fn measure_compilation() -> Result<(Duration, i64), Box<dyn std::error::Error>> {
    let start = Instant::now();

    // Run the Rust compiler as a subprocess...
    let rustc_output = Command::new("rustc")
        .arg("--version")
        .output()?;

    if !rustc_output.status.success() {
        return Err(Box::new(format_err![early_error!]));
    }

    let duration = start.elapsed();

    // Measure resident set size (RSS) using rusage...
    let rss = get_resident_set_size().unwrap() as i64;

    Ok((duration, rss))
}
```

