["Here is a skeleton code for initializing AES-256-CBC cipher with OpenSSL library in C, please note that this example does not include error handling which you would want to add when developing real applications. 

```c
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <string.h>

EVP_CIPHER_CTX* initializeAES256CBCCipher(const char *password) {
    unsigned char key[SHA_DIGEST_LENGTH];

    // Create SHA-1 hash from the password
    SHA1((unsigned char *)password, strlen(password), key);

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        // Error handling here...
        return NULL;
    }

    // Set the IV length and key length to fixed values
    int ivLength = EVP_CIPHER_CTX_iv_length(ctx);
    unsigned char *iv = (unsigned char *)malloc(ivLength);
    memset(iv, 0, ivLength);

    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, ivLength, NULL)) {
        // Error handling here...
        return NULL;
    }

    if (!EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv)) {
        // Error handling here...
        return NULL;
    }

    EVP_CIPHER_CTX_set_key_length(ctx, SHA_DIGEST_LENGTH);

    free(iv);

    return ctx;
}
```
This code snippet generates a SHA-1 hash from the password and uses it as the key for AES encryption. It also sets the IV (initialization vector) length to the recommended value. The function returns an EVP_CIPHER_CTX object that can be used to perform AES encryption or decryption using the OpenSSL library's APIs.
"]

