2. Main Library:
```rust
extern crate ring;
use std::error::Error;
use ring::hmac::{sign, verify_key};
use ring::pbkdf2::{Pbkdf2, DEFAULT_ITERATIONS, pbkdf2};
use std::sync::Arc;
use aes_gcm::aead::Aead;
use aes_gcm::aead::openssl::OpenSSLAead;

pub struct AESCipher {
    cipher: Arc<dyn Aead>,
}

impl AESCipher {
    pub async fn new(password: &str) -> Result<Self, Box<dyn Error>> {
        let salt = get_random_bytes(); // Implement this function.
        let key = derive_key(password.as_bytes(), &salt)?;
        let cipher = OpenSSLAead::new_variable_key(key).unwrap();

        Ok(AESCipher { 
            cipher: Arc::new(cipher) 
        })
    }

    pub fn encrypt(&self, data: &[u8]) -> Result<Vec<u8>, Box<dyn Error>> {
        let nonce = get_random_bytes(); // Implement this function.
        Ok(self.cipher.seal(nonce.as_ref(), data).unwrap())
    }

    pub fn decrypt(&self, data: &[u8], nonce: &[u8]) -> Result<Vec<u8>, Box<dyn Error>> {
        Ok(self.cipher.open(nonce, data).unwrap())
    }
}

fn derive_key(password: &[u8], salt: &[u8]) -> Result<Vec<u8>, Box<dyn Error>> {
    let pbkdf2 = Pbkdf2::new(
        sign::Key::from_raw([0; 32]),
        &pbkdf2(password, salt, DEFAULT_ITERATIONS),
    );
    Ok(pbkdf2.unwrap().verify_key().as_ref().to_vec())
}
```
This is a simple implementation of an AES-GCM cipher in Rust using the `ring` crate for cryptographic operations and `aes-gcm` for the actual encryption/decryption. 

