#include <openssl/evp.h>
#include <string.h>

void initAESCipher(unsigned char* key_data, int key_data_len, unsigned char** encryptedMessage) {
    /* Don't hard code your keys and use a secure way to handle them */
    unsigned char *key = "0123456789abcdef"; // 16 byte key for AES-128

    /* Create and initialise the context */
    EVP_CIPHER_CTX ctx;
    EVP_CIPHER_CTX_init(&ctx);

    // Set encryption algorithm
    EVP_EncryptInit_ex(&ctx, EVP_aes_128_cbc(), NULL, key, NULL);

    /* Provide the message to be encrypted, and obtain the encrypted output.
       EVP_EncryptUpdate can be called multiple times if necessary */
    int len;
    EVP_EncryptUpdate(&ctx, *encryptedMessage, &len, key_data, key_data_len);

    // Finalise encryption process
    EVP_EncryptFinal_ex(&ctx, *encryptedMessage+len, &len);

    /* Clean up */
    EVP_CIPHER_CTX_cleanup(&ctx);
}
```
