// Global configuration and logging categories
log4c_category_t* mycat = NULL;
int MAX_THREADS = 10;
char* EXTERNAL_API_URL = "http://example.com/api";
CURL *curl;
CURLcode res;
struct curl_slist *headers = NULL;

// Function to extract metadata from TIFF file
void parseTIFF(char *filename) {
    TIFF* tif = TIFFOpen(filename, "r");
    if (tif) {
        // Perform the extraction of metadata here

        TIFFClose(tif);
    } else {
        log4c_category_log(mycat, LOG4C_PRIORITY_ERROR, 
            "Could not open file %s", filename);
    }
}

// Function to handle external API calls and error handling
void postToAPI() {
   // Setup CURL for HTTP POST operation
   headers = curl_slist_append(headers, "Content-Type: application/json");
   curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

   res = curl_easy_perform(curl);
   if (res != CURLE_OK) {
      log4c_category_log(mycat, LOG4C_PRIORITY_ERROR, 
         "Failed to post data: %s", curl_easy_strerror(res));
   }
}

// Thread function for concurrent processing of files
void* threadFunction(void *filename) {
    parseTIFF((char*) filename);

    // For distributed processing, call API here and handle network errors.
    // postToAPI();

    return NULL;
}

// Main function for command line interface, file reading, error handling etc
int main(int argc, char *argv[]) {
    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    // Logging setup
    log4c_init();
    mycat = log4c_category_get("mycat");

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();

    // Open directory and process files
    DIR *dir;
    struct dirent *ent;
    if ((dir = opendir ("/path/to/your/directory")) != NULL) {
        while ((ent = readdir (dir)) != NULL && thread_count < MAX_THREADS) {
            // Create threads to handle files asynchronously. 
            pthread_create(&(threads[thread_count++]), NULL, threadFunction, ent->d_name);
        }
    closedir (dir);
    } else {
      log4c_category_log(mycat, LOG4C_PRIORITY_ERROR, "Could not open directory");
    }

    // Wait for threads to finish and clean up.
    int i;
    for (i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    curl_easy_cleanup(curl);
    log4c_fini();

    return 0;
}
```
This is a basic example and does not include all the functionalities, error handling, logging, concurrency management etc. that you may need for a production-level solution. It's advised to study each library separately and then come up with your specific implementation plan. Testing this code will require a TIFF image and an external API server.
