['Here is a skeleton of how your C library might start:

```c
#include <stdio.h>
#include <stdlib.h>
#include <dlfcn.h>
#include <pthread.h>

// Structs for the plugin and registry
typedef struct {
    void* handle;
} Plugin;

typedef struct {
    Plugin** plugins;
    int size;
    pthread_mutex_t lock;
} Registry;

Registry* create_registry() {
    Registry* reg = malloc(sizeof(Registry));
    reg->plugins = NULL;
    reg->size = 0;
    pthread_mutex_init(&reg->lock, NULL);
    return reg;
}

void destroy_registry(Registry* reg) {
    for (int i = 0; i < reg->size; ++i) {
        dlclose(reg->plugins[i]->handle);
        free(reg->plugins[i]);
    }
    free(reg->plugins);
    pthread_mutex_destroy(&reg->lock);
    free(reg);
}

void add_plugin(Registry* reg, const char* path) {
    void* handle = dlopen(path, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error loading plugin from %s: %s\n", path, dlerror());
        return;
    }

    pthread_mutex_lock(&reg->lock);
    reg->plugins = realloc(reg->plugins, (reg->size + 1) * sizeof(Plugin*));
    Plugin* plugin = malloc(sizeof(Plugin));
    plugin->handle = handle;
    reg->plugins[reg->size++] = plugin;
    pthread_mutex_unlock(&reg->lock);
}
``` 

This is a basic example and does not include error handling, thread safety, or dynamic service discovery. For actual development, you would need to fill in the details including creating functions for loading plugins, implementing the token validation logic, creating a caching strategy, developing an error handling system, ensuring security compliance, and designing scalability measures. 

