public class DynamicImageProcessor
{
    private BlockingCollection<Task> TaskQueue { get; set; }
    private ConcurrentDictionary<string, TaskCompletionSource<object>> ImageProcessingResults { get; set; }

    // Other required properties and fields

    public DynamicImageProcessor(int batchSize)
    {
        if (batchSize <= 0)
            throw new ArgumentException("Batch size must be a positive integer");

        TaskQueue = new BlockingCollection<Task>(new ConcurrentQueue<Task>(), batchSize);
        ImageProcessingResults = new ConcurrentDictionary<string, TaskCompletionSource<object>>();
    }

    public void SubmitImageTask(string imagePath)
    {
        // Create a task and enqueue it to the queue with completion source
        var tcs = new TaskCompletionSource<object>();

        if (!ImageProcessingResults.TryAdd(imagePath, tcs))
            throw new InvalidOperationException("Task for this image already exists");

        var task = new Task(() =>
        {
            // Implement your processing logic here...

            // On completion of the task, set the result to complete the task completion source
            tcs.SetResult(null);
        });

        TaskQueue.Add(task);
    }

    public async Task GetProcessedImageAsync(string imagePath)
    {
        // Get the task completion source for the given image path and wait for its result
        if (ImageProcessingResults.TryRemove(imagePath, out var tcs))
            await tcs.Task;

        throw new InvalidOperationException("No such image");
    }

