In C:
```c
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <json-c/json.h> 

struct bundle {
    int size;
    struct json_object *items;
};

int loadBundle(const char* path, struct bundle **bundle) {
    FILE *fp = fopen(path, "r");
    if (fp == NULL) return errno; //Return the system error code.

    char buffer[2048];
    size_t bytesRead = fread(buffer, 1, sizeof(buffer), fp);
    if (bytesRead == 0 && !feof(fp)) { //Error occurred or End-Of-File reached.
        return errno;
    }

    json_object *parsed_json = json_tokener_parse(buffer);
    struct bundle *bndl = malloc(sizeof(struct bundle)); 
    if (bndl == NULL) return ENOMEM; //Out of memory.

    bndl->items = json_object_object_get(parsed_json, "items");
    bndl->size = json_object_array_length(bndl->items);

    *bundle = bndl; //Return the bundle by modifying the pointer passed in.
    return 0; 
}
```
