class HttpServer {
public:
    HttpServer(boost::asio::io_service& io_service, short port) : acceptor_(io_service, tcp::endpoint(tcp::v4(), port)), socket_(io_service) {}

    void start() {
        doAccept();
    }
private:
    void doAccept() {
        acceptor_.async_accept(socket_, [this](boost::system::error_code ec){
            if (!ec) {
                handleRequest();
            }
            else {
                std::cout << "Error accepting connection" << std::endl;
            }
            doAccept();
        });
    }

    void handleRequest() {
        // parse request and handle it here
    }

    tcp::acceptor acceptor_;
    tcp::socket socket_{acceptor_.get_io_service()};
};

int main(int argc, char* argv[]) {
    try {
        boost::asio::io_service ioService;
        HttpServer server(ioService, 80);
        server.start();
        ioService.run();
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
    }

    return 0;
}
```

