std::atomic<bool> stopFlag{false};
std::mutex eventRecordsMutex;
std::vector<std::unique_ptr<EventRecord>> eventRecords;
std::chrono::seconds retryInterval{1};
const std::size_t maxEvents = 1024; // Define your maximum events here
extern ExternalDataSource externalDataSource;

void batch_event_population() {
    while (!stopFlag) {
        try {
            const char* metadata = nullptr;
            if (externalDataSource.fetchMetadata(&metadata)) {
                std::lock_guard<std::mutex> lock(eventRecordsMutex);

                // Generate a unique event type within a predefined range
                std::random_device rd;
                std::mt19937 gen(rd());
                std::uniform_int_distribution<> dis(0, static_cast<int>(EventType::Count) - 1); // Replace Count with your maximum event type value
                EventType eventType = static_cast<EventType>(dis(gen));

                if (eventRecords.size() < maxEvents) {
                    auto now = std::chrono::system_clock::now();
                    auto timestamp = std::chrono::system_clock::to_time_t(now);

                    eventRecords.push_back(std::make_unique<EventRecord>());
                    eventRecords.back()->timestamp = timestamp;
