                    eventRecords.back()->metadata = metadata;
                } else {
                    // Handle the case where maximum events have been reached
                }
            } else {
                // Handle cases when fetchMetadata fails
                ++retryInterval;
                std::this_thread::sleep_for(std::chrono::seconds(retryInterval));
