<?php
interface ExternalAPIClient {
    public function request($endpoint, $data);
}

class RetryingAPIClient implements ExternalAPIClient {
    private $client;

    public function __construct(ExternalAPIClient $client) {
        $this->client = $client;
    }

    public function request($endpoint, $data) {
        for ($i = 0; $i < 3; $i++) {
            try {
                return $this->client->request($endpoint, $data);
            } catch (NetworkException $e) {
                // Log error and retry
                error_log("Failed to connect to external API");
                continue;
            }
        }

        throw new NetworkException("Unable to communicate with external API after 3 attempts");
    }
}

