	err := syncFiles(bucket, key)
	if err != nil {
        log.Fatalf("Failed to sync files: %v", err)
    }
}

func syncFiles(bucket string, key string) error {
	// Download file from S3
	downloader := s3manager.NewDownloader(sess)

    file, err := os.Create(key)
    if err != nil {
        return fmt.Errorf("failed to create file %q, %v", key, err)
	}

	// Write the contents of S3 Object to the file
    _, err = downloader.Download(file, &s3.GetObjectInput{
        Bucket: aws.String(bucket),
        Key:    aws.String(key),
    })

    if err != nil {
		return fmt.Errorf("failed to download file, %v", err)
	}

	// Upload the file to another S3 bucket or a remote storage like Google Cloud Storage
	s3Svc := s3.New(sess)
	_, err = s3Svc.PutObject(&s3.PutObjectInput{
        Bucket: aws.String("anotherBucket"),
        Key:    aws.String(key),
        Body:   file,
	})
	if err != nil {
		return fmt.Errorf("failed to upload file, %v", err)
	}

	fmt.Printf("File uploaded successfully: %q\n", key)
    return nil
}
```
This is a simple example and doesn't include many features you mentioned such as parallel uploads/downloads with adaptive chunk sizes, error handling, security measures, scalability for multi-cloud and hybrid cloud environments etc. 

The complete codebase would be far too large to fit here, but I hope this gives a good starting point to get started in the right direction. It's also recommended to break down such complex tasks into smaller parts and tackle them individually, as it will make your work easier to manage.
']

