#include <iostream>
#include <vector>
using namespace std;

class Node {
public:
    int id; // This should be some kind of unique identifier
    vector<Node*> edges; 

    Node(int n) : id(n) {}
};

class Graph {
private:
    vector<Node*> nodes;
public:
    void addNode(int id) {
        nodes.push_back(new Node(id));
    }

    void addEdge(int src, int dest) {
        for (auto node : nodes) {
            if (node->id == src) {
                for (auto edgeNode : nodes) {
                    if (edgeNode->id == dest) {
                        node->edges.push_back(edgeNode);
                        break;
                    }
                }
                break;
            }
        }
    }

    void removeEdge(int src, int dest) {
        for (auto node : nodes) {
            if (node->id == src) {
                for (unsigned int i = 0; i < node->edges.size(); ++i) {
                    if (node->edges[i]->id == dest) {
                        node->edges.erase(node->edges.begin() + i);
                        break;
                    }
                }
            }
        }
    }

    void printGraph() {
        for (auto node : nodes) {
            cout << "Node: " << node->id << " Edges: ";
            for (auto edgeNode : node->edges) {
                cout << edgeNode->id << ' ';
            }
            cout << endl;
        }
    }
};
```
Please note that this is a very basic example and lacks many features you'd typically expect from a professional Graph class. It doesn't handle adding duplicate edges, it doesn't have error checking or exception handling, and it doesn't properly deallocate memory when nodes are removed. You would need to add these features in a real-world application.
