const express = require('express');
const app = express();
app.use(express.json());

class MarkdownProcessor {
  constructor(directoryPath) {
    this.directoryPath = directoryPath;
  }

  async processFiles() {
    const files = await readdir(this.directoryPath);

    // Use Promise.all for parallel processing
    return Promise.all(files.map(file => {
      fs.readFile(`${this.directoryPath}/${file}`, 'utf8', (err, data) => {
        if (err) throw err;

        const html = marked(data); // convert markdown to HTML using external library

        return cms.post('/markdown-files', { file: file, content: html }); // integrate with CMS 
      })
    }));
  }
}

app.get('/process', async (req, res) => {
  const processor = new MarkdownProcessor(/* directory path */);

  try {
    await processor.processFiles();

    // Return success response
    return res.json({ message: 'Files processed successfully' });
  } catch (error) {
    console.log('Error processing files', error);

    // Return error response
    return res.status(500).json({ error: 'An error occurred while processing the files.'});
  }
});
```

Please note that in order to use this code you need to have Node.js and Express installed, as well as a Markdown parsing library such as `marked`. Also, replace the `/* directory path */` with actual path where your markdown files are located and fill out the options for `CMSClient` based on your external CMS client API details.
