class ThemeCacheManager:
    def __init__(self):
        self.cache = {}

    # Fetch theme from external service or local cache
    def get_theme(self, theme_id):
        if theme_id in self.cache:
            return self.cache[theme_id]

        try:
            theme = fetch_from_external_service(theme_id)
            # Add to local cache for faster access next time
            self.cache[theme_id] = theme
            return theme
        except NetworkError:
            # Use fallback mechanism
            pass

    # Retry policy function
    def retry_policy(self, func, retries=3):
        for i in range(retries):
            try:
                return func()
            except Exception as e:
                if i == retries - 1:
                    raise e
